window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-10T14:59:53.755Z","stories":{"760e0591-91c2-4b7a-aea8-5a33ba5d86b1":{"publicId":"760e0591-91c2-4b7a-aea8-5a33ba5d86b1","title":"Anthropic 发布 Fable 5.2 与 Mythos 5.2，多项评测登顶","status":"active","sourceCount":33,"reportCount":66,"firstReportAt":"2026-11-08T16:00:00.000Z","latestAt":"2026-11-10T14:07:47.000Z","latest":"Anthropic Fable 5.2 在 Remote Labor Index 上以 41.3% 领跑真实自由职业任务","digest":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，两者基于同一底层模型，主打编码、推理和视觉能力。Fable 5.2 当日起向所有付费计划开放，并上线 Claude Platform 及 AWS、Google Cloud、Microsoft Azure 等主要云平台；Mythos 5.2 移除部分安全限制，仅向通过网络安全或生命科学验证计划申请的组织开放。Fable 5.2 定价为每百万输入 token 8 美元、输出 token 40 美元，较 Fable 5.1 的 10/50 美元下降 20%，上下文 1M。\n\n多项第三方评测显示 Fable 5.2 登顶：Artificial Analysis Intelligence Index v5 以 65 分居首，领先 Gemini 4 Carbon（60）和 Claude Opus 5.5（59）；Arena Code Arena: WebDev 以 1832 分排名第一；ARC-AGI-2 得分 93.8%，为 ARC Prize 见过的第三高，仅次于 GPT-6 Astra 的 95.0% 和 GPT-6.1 Sol 的 94.2%。ARC Prize 同时说明，在标准测试框架下以 max 推理运行时，55 个半私有游戏中有 28 个触及 12 小时时限，max 得分 65.7%，低于 xhigh 的 81.2%；且已发布版本在 medium 和 xhigh 推理强度下的调优与其此前评估的检查点不同。Scale Labs 与 CAIS 的 Remote Labor Index 上，Fable 5.2 以 41.3% 排名第一。\n\nFable 5.2 已接入 Cursor、Perplexity、Devin、OpenRouter、Google Cloud 等平台。Anthropic 向订阅用户发放 Fable 重置次数：Pro 用户一次，Max、Ultra 和 Team Premium 最多三次，取决于订阅时长，可在明年 3 月 8 日前使用；Pro 和 Team Standard 另有一周试用期，上限为每周额度的一半。Addy Osmani 称，Fable 5.2 的 token 消耗量大，按单任务计算成本与 Fable 5.1 大致相同，尽管单价便宜了 20%。","digestUpdatedAt":"2026-11-10T14:10:15.405Z","reports":[{"id":"oesqqhekbr8e1bekkcitpguqh","title":"Anthropic Fable 5.2 在 Remote Labor Index 上以 41.3% 领跑真实自由职业任务","summary":"The Decoder 报道，Anthropic 新模型 Fable 5.2 在 Scale Labs 和 Center for AI Safety 的 Remote Labor Index 基准上以 41.3% 排名第一，该测试衡量 AI 智能体能否把真实自由职业项目做到让付费客户接受的质量。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:07:47.000Z","url":"https://the-decoder.com/anthropics-fable-5-2-completes-41-percent-of-real-freelance-jobs-up-from-2-5-percent-a-year-ago/"},{"id":"hynj57ofu1z4qk45g0cau922d","title":"那些做机器人模型的公司 此刻是什么心情💢 会写代码和用工具的 LLM 吞噬一切😜","summary":"那些做机器人模型的公司 此刻是什么心情💢 会写代码和用工具的 LLM 吞噬一切😜","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-10T07:49:56.000Z","url":"https://x.com/indigox/status/2120061380892193023"},{"id":"nnl670lkd0mynnkspz9f1wmgp","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，重登榜首但每任务成本上升","summary":"Anthropic 发布 Claude Fable 5.2 和 Mythos 5.2，Fable 5.2 在 Artificial Analysis Intelligence Index v5 以 65 分登顶，超过 Gemini 4 Carbon 和 Opus 5.5。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-10T06:34:44.000Z","url":"https://latent.space/p/ainews-fable-5-2-retakes-world-1-llm-spot-as-ant-ipo-roadshow-begins/"},{"id":"ob980onmw1uvlrmardsbv4mbp","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，编码基准超 GPT-6 Astra","summary":"Anthropic 于 11 月 10 日发布 Claude Fable 5.2 与 Claude Mythos 5.2 两款模型，官方称输出速度最高提高 30%，成本下降 20%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T05:52:12.373Z","url":"https://www.ithome.com/1/024/796.htm"},{"id":"spldx7fx85cpl890x6b8gr5u9","title":"Claude Fable 5.2 登顶 Arena WebDev 榜，比 Fable 5.1 快 30% 且降价","summary":"Anthropic 的 Claude Fable 5.2 (xHigh) 以 1832 分登顶 Arena 的 Code Arena: WebDev 榜，超过 Claude Opus 5.5 (Max) 的 1818 和 Gemini 4 Carbon (High) 的 1768。该版本比 Fable 5.1 快至多 30%，价格从每 M tokens $10/$50 降至 $8/$40。Arena 同时发布了 17 个生成示例视频，涵盖 3D 世界、可玩游戏、网页 UI、数据可视化和代码生成的交互动画。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-10T00:19:40.000Z","url":"https://x.com/arena/status/2119948067449536733"},{"id":"lfw4cc14h85i07c00tah6pc90","title":"Anthropic 发布 Fable 5.2 与 Mythos 5.2，llm-anthropic 0.31 已支持","summary":"Anthropic 发布 Fable 5.2 和 Mythos 5.2，作者已将其加入 llm-anthropic 0.31，可用 llm -m claude-fable-5.2 直接调用。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-09T23:58:46.000Z","url":"https://simonwillison.net/2026/Nov/9/llm-anthropic/"},{"id":"ljc2f7hyvtplkggpez6tivvnz","title":"实测Claude Fable 5.2：审美与细节的长任务能力体验","summary":"卡兹克凌晨实测刚全渠道上线的Claude Fable 5.2，称其在视频动效、Three.js 3D和上海苹果静安店3D网页等任务中审美与细节表现突出，跑分AA指数65分登顶。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T23:53:55.000Z","url":"https://x.com/Khazix0918/status/2119941585538572390"},{"id":"u1n6sw21ocnfdd1sdbd4i9m7z","title":"Claude Fable 5.2 (xHigh) 以 1832 分登顶 Code Arena: WebDev 榜单","summary":"Anthropic 发布的 Claude Fable 5.2 (xHigh) 在 Arena 的 Code Arena: WebDev 榜单以 1832 分排名第一，超过 Claude Opus 5.5 (Max) 的 1818 分和 Gemini 4 Carbon (High) 的 1768 分。据 Arena 数据，该模型比 Fable 5.1 快最多 30%，价格从每百万 tokens $10/$50 降至 $8/$40，Agent Arena 分数即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T23:52:24.000Z","url":"https://x.com/arena/status/2119941204003770690"},{"id":"po2cdt1whxfqyfew3e81l8mb0","title":"实测 Claude Fable 5.2：一次直出视频与 3D 网页，审美与细节表现突出","summary":"Anthropic 凌晨正式发布 Claude Fable 5.2，作者第一时间实测视频动效、Three.js 3D 场景和苹果静安店 3D 网页等 10 个任务，全部一次直出，未发现生成视频中的事实错误。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-09T23:21:03.000Z","url":"https://mp.weixin.qq.com/s/sKoVHL_oNsik9vtUjr0lHg"},{"id":"yoiln3nl94gd0t3pahyhpl1xu","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，API 调用费下降 20%","summary":"Anthropic 于 11 月 9 日发布 Claude Fable 5.2 和 Claude Mythos 5.2，基于同一底层模型，前者面向普通用户，后者面向通过审核的网络安全和生命科学机构。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-09T23:14:28.957Z","url":"https://www.ithome.com/1/024/573.htm"},{"id":"dmwbvf5xa3txsm013y0pfgcgn","title":"Rohan Paul 转述 Claude Fable 5.2 完成 23 年未解的黑洞计算","summary":"Rohan Paul 转发 @claudeai 的消息称，Claude Fable 5.2 解决了两个与黑洞相关的理论物理开放问题，其中一项是悬置 23 年的繁琐计算。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T22:59:11.000Z","url":"https://x.com/rohanpaul_ai/status/2119927810517324048"},{"id":"h5nu7w8t9ueaz2etbcj5a2bzx","title":"Fable 5.2 token 消耗高，单任务成本与 5.1 相当","summary":"关于 Fable 5.2 需要说明一点：它的 token 消耗量很大。\n\n在我们的测试中，这通常意味着按单个任务计算，它的成本与 Fable 5.1 大致相同，尽管 token 单价便宜了 20%。\n\n提醒一下那些注意到降价的人！","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-09T21:37:08.000Z","url":"https://x.com/addyosmani/status/2119907165007945813"},{"id":"yn7rlom00o5fgdbcfssna1r04","title":"Claude Fable 5.2 视频能力演示：为 ChatGPT 四周年庆生","summary":"用户用 Claude Fable 5.2 为即将四周年的 ChatGPT 提前制作了一支庆生视频，称其视频能力又大幅进化，节奏和动效表现突出。推文未给出具体参数或评测数据，仅评价细节与节奏“强无敌”，并期待 OpenAI 后续拿出更好的产品。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T21:17:54.000Z","url":"https://x.com/Khazix0918/status/2119902325460590834"},{"id":"obzr8x05lsufq7bknpsxpxvlk","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，IPO 前重夺性能领先","summary":"Anthropic 发布 Claude Fable 5.2 和 Mythos 5.2，两模型同一基础但访问策略不同：Fable 带网络安全与生物安全护栏向所有用户开放，Mythos 移除部分限制，仅向通过 Verification Programs 申请的组织开放。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T21:15:23.000Z","url":"https://the-decoder.com/claude-fable-5-2-and-mythos-5-2-cement-anthropics-ai-lead-just-before-its-ipo/"},{"id":"v98n3a3ihdr862ehiug7tjqqe","title":"Claude Fable 5.2 在 Google Cloud 上线","summary":"Claude Fable 5.2 现已在 Google Cloud 可用，支持构建长时间运行的智能体。该版本面向跨多个仓库和 monorepo 的大型模糊问题、可持续数小时至数天的无人值守工作流（含子智能体协调），以及困难物理计算、形式化证明和数据分析等科学与数据流水线。","sourceName":"Google AI：DEV 作者专属（RSS）","firstParty":false,"publishedAt":"2026-11-09T21:15:16.000Z","url":"https://dev.to/googleai/claude-fable-52-is-available-on-google-cloud-15kn"},{"id":"eo8g3wddjvxgmw1c3rfnomgtd","title":"Claude Fable 5.2 视频能力演示：为 ChatGPT 四周年庆生","summary":"作者用 Claude Fable 5.2 为即将到来的 ChatGPT 四周年提前制作了一支庆生视频，称其视频能力又大幅进化，节奏和动效表现很强。推文未给出具体参数、分数或价格信息。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T21:08:05.000Z","url":"https://x.com/Khazix0918/status/2119899854323540238"},{"id":"qbgn6yju6qvr6i7mb4bkk8y77","title":"Anthropic 发布 Claude Fable 5.2，Claude Mythos 5.2 开放专项申请","summary":"Anthropic 宣布 Claude Fable 5.2 当日起面向所有付费计划开放。从事网络安全或生物医学研究有益应用的组织可申请访问 Claude Mythos 5.2，详情见 https://www.anthropic.com/claude-fable-and-mythos-5-2。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:39.000Z","url":"https://x.com/claudeai/status/2119899492778398163"},{"id":"ktl31hzsgulxlz6vbxolyldc9","title":"Fable 5.2 验证极小宇宙黑洞突变","summary":"1983年，物理学家证明，当某些更大的理论宇宙升温时，黑洞会非常突然地形成。2003年，有人提出了一项计算，用于检验这一现象在一组极小的宇宙中是否同样成立。\n\nFable 5.2 发现，那里的转变同样是突变的。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:38.000Z","url":"https://x.com/claudeai/status/2119899487044825293"},{"id":"p3jlan36o3hidm58amjwae14z","title":"Fable 5.2 破解模模块化自举极限","summary":"在第二个物理问题中，Fable 5.2 找到了被称为“模模块化自举”的 15 年历史技术最简单版本的精确极限。该技术用于在理论宇宙中排除量子引力的候选理论。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:38.000Z","url":"https://x.com/claudeai/status/2119899488995131439"},{"id":"lgplhadzt9g0f4s2s08eqyxah","title":"Fable 5.2 解决黑洞理论物理难题","summary":"Fable 5.2 解决了理论物理中两个与黑洞相关的开放问题。\n\n在第一个问题中，Fable 5.2 完成了一项长达 23 年未解出的繁重计算。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:37.000Z","url":"https://x.com/claudeai/status/2119899484373369278"},{"id":"w45lbhhprl6qnfys5jtkrszi5","title":"Claude 订阅用户重置次数说明","summary":"Pro 用户可获得一次重置，Max、Ultra 和 Team Premium 用户最多可获得三次，具体取决于你的订阅时长：\nhttps://support.claude.com/en/articles/17506494-claude-fable-5-2-launch-offers","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-09T20:32:11.000Z","url":"https://x.com/bcherny/status/2119890820186976763"},{"id":"trwrvd5kw6o78ulj98yggbvxc","title":"Higgsfield MCP 接入 Claude 试用 Fable 5.2","summary":"现在就在 Claude 中通过 Higgsfield MCP 试用 Fable 5.2：\nhttps://higgsfield.ai/mcp?tab=claude","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-09T20:06:54.000Z","url":"https://x.com/higgsfield/status/2119884456651866439"},{"id":"ugn21ui1m8kftffpe2c95qlkx","title":"Claude Fable 5.2 上线 Higgsfield，开放 3 天免费试用","summary":"Higgsfield 宣布 Claude Fable 5.2 已在 Higgsfield MCP 上线，提供 3 天免费不限量使用全部顶级视频和图像模型。作者称该 Anthropic 新模型擅长 3D 建模、视觉推理、computer use 和编码；引用内容提到 Claude Fable 5.2 与 Claude Mythos 5.2 在编码、推理和视觉方面有提升。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-09T20:06:53.000Z","url":"https://x.com/higgsfield/status/2119884452054937656"},{"id":"i2tveljooudnlde5gbtpps79q","title":"Claude Fable 5.2 上线 Agent Arena，用户可实测，评分即将公布","summary":"Arena 宣布 Anthropic 的 Claude Fable 5.2 已上线 Agent Arena，用户可前往实测，官方评分即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T19:58:21.000Z","url":"https://x.com/arena/status/2119882304718069874"},{"id":"shwr0td0cprvq5e36s0jmar7t","title":"Cursor 公布 Fable 5.2 定价与推理档位变化","summary":"Fable 5.2 定价为每百万输入 token 8 美元、每百万输出 token 40 美元，比 Fable 5.1 低 20%。\n\n其 effort 档位的行为与 Fable 5.1 不同，因此请从默认档位开始，不要沿用旧设置。\n\n对比各 effort 档位：https://cursor.com/evals","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-09T19:52:32.000Z","url":"https://x.com/cursor_ai/status/2119880841728000057"},{"id":"lwtt7st2cponcbtt0twrzlvr9","title":"Claude Fable 5.2 上线 Cursor，CursorBench 默认档得分 56.9%","summary":"Cursor 宣布 Claude Fable 5.2 现已在 Cursor 中可用。Fable 5.2 在默认推理力度下 CursorBench 得分 56.9%，高于 Fable 5.1 的 49.2%；在最高推理力度下以 60% 位居 CursorBench 榜首，默认档平均每任务成本为 $9.70。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-09T19:52:29.000Z","url":"https://x.com/cursor_ai/status/2119880829212172509"},{"id":"m23i0fgxrk1t2gqysu6mqv82s","title":"Artificial Analysis 评测 Claude Fable 5.2：以 65 分登顶 Intelligence Index v5","summary":"Artificial Analysis 评测 Anthropic 发布的 Claude Fable 5.2，其在 Artificial Analysis Intelligence Index v5 以 65 分登顶，领先 Gemini 4 Carbon（60）和 Claude Opus 5.5（59）。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-09T19:45:12.000Z","url":"https://x.com/ArtificialAnlys/status/2119878995386982508"},{"id":"h2f58ke3re6fq8ottpst2kyev","title":"Fable 5.2 重置机制上线","summary":"太喜欢了。Fable 5.2 重置。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T19:38:51.000Z","url":"https://x.com/rohanpaul_ai/status/2119877395742437590"},{"id":"lr06w7ixk1mrwmiu8noiwrnrs","title":"Claude Fable 5.2 上线 Perplexity","summary":"Claude Fable 5.2 现已在 Perplexity Computer 中向 Pro 和 Max 订阅用户开放，并在 Search 中向 Max 订阅用户开放。\n\n在我们的 WANDR 基准测试中，它实现了性能与效率的帕累托前沿，以每任务 14.51 美元的成本创下 0.851 的纪录分数。","sourceName":"X：Perplexity (@perplexity_ai)","firstParty":false,"publishedAt":"2026-11-09T19:29:41.000Z","url":"https://x.com/perplexity_ai/status/2119875089974104489"},{"id":"yjtr1evpobvoxm47szz1h6dmf","title":"Claude Fable 5.2 上线 OpenRouter：1M 上下文，输入 $8/M、输出 $40/M","summary":"Anthropic 的 Claude Fable 5.2 上线 OpenRouter，定价为输入 $8/M、输出 $40/M，上下文 1M，输出速度比 Fable 5.1 快至 30%。Anthropic 公布的成绩包括 FrontierSWE v2 69.9%、OSWorld 2.1 89.3%、Humanity's Last Exam（带工具）74.2%，详情见 http://openrouter.ai/anthropic/claude-fable-5.2","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-09T19:29:40.000Z","url":"https://x.com/OpenRouter/status/2119875084521447767"},{"id":"vyl46w9gp41tiw4mavmq1nks0","title":"Anthropic 发布 Mythos 5.2 与 Fable 5.2，METR 报告引发 RSI 担忧","summary":"Anthropic 发布 Mythos 5.2 和 Fable 5.2，称新模型在编码、推理和视觉方面有提升。Fable 输入价格从每百万 token $10 降至 $8，低于竞争对手 GPT-6 Astra，响应速度提升 30%，并通过 Enterprise Frontier Safeguards 支持零数据保留（ZDR）政策。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T19:24:51.000Z","url":"https://techcrunch.com/2026/11/09/anthropic-releases-new-mythos-and-fable-models-amid-rsi-concerns/"},{"id":"qhzj0er5hgffkbmtnou3exjhx","title":"Claude 向订阅用户发放 Fable 重置次数","summary":"重置次数来了！","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-09T19:23:19.000Z","url":"https://x.com/adocomplete/status/2119873489679327578"},{"id":"r8v58z5d8lz5ro3q7j4yj90tq","title":"Claude Code v2.1.321 发布：新增 Claude Fable 5.2 为默认 Fable 模型","summary":"Claude Code 发布 v2.1.321，新增 Claude Fable 5.2（claude-fable-5-2）并设为默认 Fable 模型，支持 1M 上下文，价格为 $8/$40 per Mtok、缓存读取 $0.20/Mtok。","sourceName":"Claude Code：GitHub Releases（RSS）","firstParty":true,"publishedAt":"2026-11-09T19:22:30.000Z","url":"https://github.com/anthropics/claude-code/releases/tag/v2.1.321"},{"id":"y9k10za6wp1gxq3l2mvosharb","title":"Claude Fable 5.2 订阅越久重置越多","summary":"我们想为陪伴我们最久的用户多做些事。因此在 Fable 5.2 中，你订阅的时间越长，获得的 Fable 重置次数就越多。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-09T19:21:45.000Z","url":"https://x.com/bcherny/status/2119873095129550880"},{"id":"vjeqe8ie59ggfas1bbursg3ao","title":"Anthropic 发布 Claude Fable 5.2 与 Claude Mythos 5.2","summary":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，面向高难度技术挑战，在编码、推理和视觉等方面有提升。作者 Lydia Hallie 体验后认为它验证结果比 Fable 5.1 更彻底，并主要将其作为 orchestrator 搭配 Opus 5.5 使用；Pro/Max/Ultra/Team 套餐还获得至少一次免费 Fable reset。","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-09T19:16:05.000Z","url":"https://x.com/lydiahallie/status/2119871667400999166"},{"id":"q4hu7btrfoxga7slj6za15abz","title":"Fable 5.2 与 Opus 生成能力对比","summary":"对 @AnthropicAI 的 Fable 5.2 的第一印象来了。@petergostev 让它跑了 100+ 次生成，在 3D 世界、可玩游戏、网站 UI、数据可视化和动画方面与 Opus 进行对比。\n\nFable 5.2 在哪些方面有所提升，Opus 又仍在哪些方面更胜一筹，代价是什么？观看完整分析\nhttps://www.youtube.com/live/QwaU4yU0PdQ","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T19:15:48.000Z","url":"https://x.com/arena/status/2119871594403336451"},{"id":"ccr64nv9h7eryilvqf24aj22k","title":"ARC Prize 公布 Claude Fable 5.2 在 ARC-AGI-2 上取得 93.8%","summary":"ARC Prize 宣布 Claude Fable 5.2 在 ARC-AGI-2 上取得 93.8%，是其见过的第三高模型成绩，仅次于 GPT-6 Astra 的 95.0% 和 GPT-6.1 Sol 的 94.2%。完整结果见 https://arcprize.org/results/anthropic-claude-fable-5-2。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:46.000Z","url":"https://x.com/arcprize/status/2119871082756800545"},{"id":"vl2atp07nuiuo91hst8roouey","title":"ARC Prize 公布 Claude Fable 5.2 测试结果","summary":"@AnthropicAI - 排行榜：https://arcprize.org/leaderboard\n- 复现公开结果：https://github.com/arcprize/arc-agi-benchmarking\n- 测试政策：https://arcprize.org/policy\n- Claude Fable 5.2 完整结果：https://arcprize.org/results/anthropic-claude-fable-5-2","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:46.000Z","url":"https://x.com/arcprize/status/2119871084832915752"},{"id":"rvri367ocklyqxhy3evwkvxjn","title":"ARC Prize 公布 Claude Fable 5.2 在 ARC-AGI (Verified) 上的评测成绩","summary":"ARC Prize 发布 Claude Fable 5.2 在 ARC-AGI (Verified) 上的评测结果。ARC-AGI-3 得分 97.7%（成本 $18.6K，provider adapter harness）和 81.2%（成本 $21.9K，standard harness）；ARC-AGI-2 得分 93.8%（$0.98/task）；ARC-AGI-1 得分 98.5%（$0.36/task）。该模型在 standard harness 下创下 ARC-AGI-3 新高分之一（附 ARC-AGI 3 排行榜图）。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:45.000Z","url":"https://x.com/arcprize/status/2119871080525373922"},{"id":"uqzme96rbooud8mwvji044k7y","title":"ARC-AGI-3 测试中 max 推理受限","summary":"在标准测试框架下以 max 推理运行时，55 个半私有游戏中有 28 个达到了 12 小时的运行时限，限制了测试能推进的程度。max 在 ARC-AGI-3 上得分 65.7%，而 xhigh 为 81.2%；若无时限限制，我们预计 max 的得分会更高。\n\n另请注意，已发布的 Fable 5.2 在 medium 和 xhigh 推理强度下使用的调优与我们此前评估的检查点不同。low、high 和 max 未变。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:45.000Z","url":"https://x.com/arcprize/status/2119871081817284743"},{"id":"o7x1sg2wsppy841z3n0hk9grk","title":"Anthropic 发布 Claude Fable 5.2 与 Claude Mythos 5.2","summary":"Anthropic 推出 Claude Fable 5.2 和 Claude Mythos 5.2，主打编码、推理和视觉能力提升。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T19:09:53.000Z","url":"https://x.com/rohanpaul_ai/status/2119870108223033374"},{"id":"u23txiafgf94qjm5yg114bh89","title":"Perplexity 上线 Fable 5.2","summary":"Fable 5.2 现已在 Perplexity 上线。可在 Computer 中使用它，或用 Fable 创建 Teammates。在 Wide and Deep Research 任务（WANDR）上，Fable 以明显优势击败 Gemini Argon。","sourceName":"X：Aravind Srinivas（Perplexity CEO） (@AravSrinivas)","firstParty":false,"publishedAt":"2026-11-09T19:09:42.000Z","url":"https://x.com/AravSrinivas/status/2119870062408691902"},{"id":"o8cticyx44l8cqsqgab9ucl6k","title":"Claude Fable 5.2 上线 Devin Desktop","summary":"在 Devin Desktop 中试用 Claude Fable 5.2：\n\nhttps://devin.ai/desktop","sourceName":"X：Cognition (@cognition)","firstParty":false,"publishedAt":"2026-11-09T19:09:12.000Z","url":"https://x.com/cognition/status/2119869933295423888"},{"id":"rth7pxd3xqp2zkd2e1psjgtbl","title":"Claude Fable 5.2 上线 Devin Desktop 和 Devin CLI","summary":"Cognition 宣布 Claude Fable 5.2 现已在 Devin Desktop 和 Devin CLI 中可用。该模型在 FrontierCode 2.0 上以 49.1 分排名第一；相比 Fable 5.1，在低推理力度下以约三分之一的价格超过前代得分。","sourceName":"X：Cognition (@cognition)","firstParty":false,"publishedAt":"2026-11-09T19:09:11.000Z","url":"https://x.com/cognition/status/2119869931135406452"},{"id":"p7yxgjaz5d5z5plyork113xsf","title":"Anthropic 发布 Claude Fable 5.2，输出速度较 5.1 提升最多 30%","summary":"Anthropic 员工宣布 Claude Fable 5.2 今日可用，输出速度比 Fable 5.1 快最多 30%，并同系列提及 Claude Mythos 5.2 在编码、推理和视觉方面的改进。作者建议多数编码和知识任务仍首选 Opus 5.5，Fable 5.2 适合最具野心的开放式技术工作，已在 Claude Platform 所有付费计划和主要云平台开放。","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-09T19:08:09.000Z","url":"https://x.com/addyosmani/status/2119869672573251887"},{"id":"pr2nbq0lryo3dq4sx0p4litkl","title":"Ethan Mollick 评测 Claude Fable 5.2：接近 AGI 但仍呈锯齿状","summary":"Ethan Mollick 在 Claude Fable 5.2 公开前长期试用后认为，该模型已达到他定义的","sourceName":"Ethan Mollick：One Useful Thing（RSS）","firstParty":false,"publishedAt":"2026-11-09T19:04:26.000Z","url":"https://www.oneusefulthing.org/p/fable-52-and-jagged-agi"},{"id":"dvlmxdeeew9mwwn79yw4ecmmn","title":"Claude 向 Ultra 与 Team Premium 用户发放 Fable 重置次数","summary":"我们正根据你的订阅时长，向 Ultra 和 Team Premium 用户发放 Fable 重置次数：\n\n<6 个月：1 次\n6–12 个月：2 次\n>12 个月：3 次\n\n可在 3 月 8 日前随时使用。\n\nPro 和 Team Standard 用户有一周时间试用 Fable 5.2，用量上限为每周限额的一半，另加一次重置。https://support.claude.com/en/articles/17506494","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-09T19:04:19.000Z","url":"https://x.com/ClaudeDevs/status/2119868704544711108"},{"id":"i8g6jclnx6g24emcg2xrehfky","title":"Anthropic：Fable 5.2 的 preserved thinking 已覆盖全部 API 账号以防知识蒸馏","summary":"Anthropic 宣布为防止知识蒸馏，Fable 5.2 的 preserved thinking 现已覆盖所有 API 账号。编辑先前上下文可能返回 400，建议改用 compaction、context editing 或会话中途 system messages；Claude Code、Managed Agents 和 Agent SDK 会自动处理。文档见 https://platform.claude.com/docs/build-with-claude/preserved-thinking。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-09T19:04:18.000Z","url":"https://x.com/ClaudeDevs/status/2119868703265419688"},{"id":"uhx7zoo8x3uery80xuce4989u","title":"Claude API 为 Fable 5.2 推出快速模式","summary":"快速模式同样适用于 Fable 5.2。\n\n输出速度提升 2.5 倍，价格翻倍。在 Claude API 中，设置 \"speed\": \"fast\"。在 Claude Code 中，在模型选择器中切换快速模式，将通过额外用量额度计费。\n\nhttps://platform.claude.com/docs/build-with-claude/fast-mode","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-09T19:04:18.000Z","url":"https://x.com/ClaudeDevs/status/2119868701994570178"},{"id":"p0hy6y39jeozzhzd532bt1gsk","title":"Claude Fable 5.2 上线 Claude Platform 和 Claude Code，速度提升最高 30% 并降价","summary":"Claude Devs 宣布 Claude Fable 5.2 现已在 Claude Platform 和 Claude Code 可用。该模型比 Fable 5.1 快最高 30%，价格从 $10/$50 降至 $8/$40 per 1M tokens。引用内容称其与 Claude Mythos 5.2 在编码、推理和视觉方面有提升，面向高难度技术挑战。","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-09T19:04:17.000Z","url":"https://x.com/ClaudeDevs/status/2119868698613956992"}]},"d01448e7-e6ef-4224-9e13-5f4b350dd6ed":{"publicId":"d01448e7-e6ef-4224-9e13-5f4b350dd6ed","title":"英伟达董事会调查黄仁勋涉情报事件","status":"active","sourceCount":9,"reportCount":27,"firstReportAt":"2026-10-29T13:42:38.000Z","latestAt":"2026-11-10T14:33:22.000Z","latest":"The Information 报道称与英伟达 CEO 黄仁勋相关人士向中国买家转手 75 亿美元硬件","digest":"英伟达董事会11月8日启动独立调查，起因是《纽约时报》《金融时报》等报道称，公司创始人兼CEO黄仁勋成为外国情报行动的目标。调查由独立董事组成的委员会在外部律师协助下进行，黄仁勋表示全力配合；董事会称目前“没有理由认为”国家安全或公司机密已受损。黄仁勋随后在内部信中承认与涉事高管Alice Huang存在婚外情。\n\n报道称，Alice Huang是新加坡数据中心运营商Megaspeed的高管，美国情报机构认为她受中国国家安全部招募，借与黄仁勋的密切接触获取英伟达计划及对华芯片出口政策信息；相关说法来自匿名信源和一份在美方官员间传阅的备忘录。英伟达此前否认相关指控，称Megaspeed只是区域云客户，双方属例行商业往来，芯片转运指控“去年已被彻底调查并证伪”。The Information最新报道称，Alice Huang与丈夫和姐姐在中国和新加坡建立采购网络，涉及75亿美元英伟达硬件流向中国买家。\n\n美国众议院三个委员会已要求黄仁勋就与Alice Huang的往来作闭门简报。英伟达法兰克福上市股票在消息后一度跌超6%；耶鲁教授Sonnenfeld估计黄仁勋留任概率约为50-50。黄仁勋目前仍留任CEO，并已退出原定本周三在纽约举行的ElevenLabs Summit及其他演讲安排。做空机构Culper Research称，其在5月13日的报告中已质疑黄仁勋与Alice Huang关系“异常密切”。","digestUpdatedAt":"2026-11-10T14:58:15.453Z","reports":[{"id":"f1z5v9nswvnu4w2plxd4tg22t","title":"The Information 报道称与英伟达 CEO 黄仁勋相关人士向中国买家转手 75 亿美元硬件","summary":"据 The Information 报道，与英伟达 CEO 黄仁勋有染的 Alice Huang（无亲属关系）与丈夫和姐姐在中国和新加坡建立采购网络，涉资 75 亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T14:33:22.000Z","url":"https://x.com/rohanpaul_ai/status/2120162909422780789"},{"id":"z68n80gno9fz2iwdgj4wr9tyw","title":"黄仁ullah承认婚外情，Nvidia 董事会调查对方是否为中国国安部工作","summary":"周日黄仁ullah向全体 Nvidia 员工发邮件承认与 Megaspeed 高管 Alice Huang 的婚外情，其董事会已启动调查，核查该女士是否为中国国家安全部工作。Megaspeed 这家被怀疑向中国走私 Nvidia 芯片的新加坡云公司仍在继续采购芯片。","sourceName":"ChinaTalk（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:28:08.000Z","url":"https://www.chinatalk.media/p/the-spy-who-leased-me"},{"id":"kci32x4hgxrdl0v5o4xrjlxri","title":"The Verge 梳理黄仁勋与 Megaspeed 高管丑闻对 Nvidia 出口管制游说的影响","summary":"The Verge 依据《纽约时报》等报道梳理 Nvidia CEO 黄仁勋与新加坡云服务商 Megaspeed 高管 Alice Huang 的婚外情风波。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:51:58.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030328/what-could-china-get-from-jensen-huang"},{"id":"t5mqlkgq1zlspdsk77jrx1ho5","title":"Trump 就间谍指控表态支持 Nvidia CEO 黄仁勋","summary":"Trump 在与 Nvidia CEO 黄仁勋就间谍指控谈话后公开为其辩护，称黄仁勋告诉他从不认识那名女性是间谍，并表示相信他。Trump 称黄仁勋是高素质的人，提到其芯片领先十年、因复杂度难以被复制，并称相信黄仁勋因家人而深感痛苦。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T23:12:09.000Z","url":"https://x.com/rohanpaul_ai/status/2119931075325759514"},{"id":"lzsihkjga6ini01aqrzcuvtaw","title":"Nvidia CEO 黄仁勋涉中国间谍风波：承认与 Megaspeed 高管 Alice Huang 有婚外情","summary":"Nvidia CEO 黄仁勋承认与 AI 算力公司 Megaspeed 高管 Alice Huang 存在婚外情，公司已就此展开调查。美方情报报告此前指认 Alice Huang 为中国国家安全部间谍，Nvidia 与黄仁勋称目前\"没有理由认为国家安全或 Nvidia 机密遭到泄露\"。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:07:59.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030422/nvidia-jensen-huang-ai-china-alice-huang"},{"id":"zqvokl37rwbvoxzfk3c2v7964","title":"做空机构 Culper Research 曾在丑闻爆发前六个月提示 Nvidia CEO 与疑似中国间谍的关系","summary":"Nvidia 间谍丑闻爆发前六个月，做空机构 Culper Research 已在 5 月 13 日报告中质疑 CEO 黄仁勋与 Megaspeed 高管 Alice Huang 关系“异常密切”。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T22:46:09.000Z","url":"https://techcrunch.com/2026/11/09/a-short-seller-flagged-nvidia-ceos-ties-to-a-suspected-chinese-spy-six-months-before-the-scandal/"},{"id":"wtp3nz2jg6cfwlvn12lqrucy7","title":"黄仁勋因个人风波退出 ElevenLabs Summit 等演讲活动","summary":"TechCrunch 报道，Nvidia CEO 黄仁勋退出本周三在纽约举行的 ElevenLabs Summit，并取消了包括 Anthropic CEO Forum 在内的其他演讲安排，ElevenLabs 周一已确认。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T20:09:06.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huang-pulls-out-of-elevenlabs-summit-amid-nvidia-controversy/"},{"id":"jg700hxd681xxb0f0r5fn03fc","title":"黄仁勋与疑似中国间谍的婚外情令 Nvidia 中国业务承压","summary":"《金融时报》报道 Nvidia CEO 黄仁勋与 Nvidia 客户 Megaspeed 前高管 Alice Huang 存在婚外情，美国情报官员认为后者被中国情报部门招募以影响芯片出口限制。黄仁勋已承认此事并向公司致歉，Nvidia 独立董事正联合外部律师调查，国会也要求作出解释。截至 7 月 26 日的三个月内，Nvidia 来自中国总部客户的收入为 79 亿美元，约占总营收 8%。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T18:09:52.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huangs-affair-with-alleged-chinese-spy-puts-nvidias-china-ambitions-under-scrutiny/"},{"id":"q8qzxski2nw3jgr77q1mwpskg","title":"Nvidia CEO 黄仁勋陷间谍丑闻风波：The Verge 分析其公司结构与 AI 生态风险","summary":"The Verge 作者评述 The New York Times 报道的 Nvidia CEO 黄仁勋与 Megaspeed 高管 Alice Huang 的关系风波，后者被指被中国国家安全部招募，Megaspeed 曾购买 48 亿美元被限制出口的 Nvidia 芯片。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T17:36:08.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1029990/jensen-huang-the-spy-who-loved-me"},{"id":"mkmn0bduza8asy7b56mygydl2","title":"Nvidia CEO 黄仁勋承认婚外情，董事会启动独立调查","summary":"Nvidia CEO 黄仁勋在内部信中承认婚外情，此前 FT 报道称美国情报界认为其涉事对象 Alice Huang 为中国国家安全部招募的间谍。Nvidia 董事会将启动独立调查，称无理由认为国家安全或公司机密受损，黄仁勋承诺全力配合。Nvidia 法兰克福上市股票周一早盘跌超 6%。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T15:23:20.000Z","url":"https://arstechnica.com/tech-policy/2026/11/ceo-jensen-huang-admits-affair-as-nvidia-probes-possible-chinese-espionage/"},{"id":"cqmkdswfcbyr8hd49dj0ek3b8","title":"黄仁勋被指陷入蜜罐事件后，英伟达董事会展开调查","summary":"Big Technology 分析黄仁勋承认与美方情报机构认为是中方间谍的 Alice Huang 有染后，英伟达董事会已就是否泄露国家和公司机密展开调查，黄仁勋暂留任 CEO。文章认为这不只是私人丑闻，还可能削弱他在放宽对华芯片出口管制上的游说公信力，并给 Anthropic 和 Google 留出机会，同时反 AI 的民主党人可能在国会听证中以他为首个目标；中国否认相关指控。","sourceName":"Big Technology（热点 RSS）","firstParty":false,"publishedAt":"2026-11-09T15:11:49.000Z","url":"https://www.bigtechnology.com/p/the-jensen-huang-honeypot-fallout"},{"id":"xxxpa0kcnhfiyb59ylopto1y7","title":"Gary Marcus 评论：黄仁勋为对华芯片销售辩护或成其最大风险","summary":"Gary Marcus 认为，真正让黄仁勋陷入麻烦的不是他与 Alice Huang 的照片和视频，而是他近期在多次采访中持续为中国购买 Nvidia 芯片的权利辩护，几乎像中国的说客。文章还提到相关照片据称由 Alice Huang 从其微信朋友圈分享。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-09T12:47:02.000Z","url":"https://garymarcus.substack.com/p/jensen-is-cooked"},{"id":"e17dl64mjiov57c0jtwn41bxd","title":"Nvidia CEO 黄仁勋婚外情风波削弱其对严格 AI 芯片出口管制的游说","summary":"据 Bloomberg 报道，Nvidia CEO 黄仁勋在全员备忘录中承认与被美国情报机构认定为疑似中国情报人员线人的 Alice Huang（Huang Le）存在婚外关系，董事会已启动独立董事主导的调查。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T11:38:43.000Z","url":"https://the-decoder.com/nvidia-espionage-scandal-weakens-huangs-lobby-against-tighter-ai-chip-export-controls/"},{"id":"i8df3mmfly47axpbbr1p6ivh5","title":"耶鲁教授 Sonnenfeld 估计黄仁勋职位去留概率约为 50-50","summary":"Nvidia 董事会宣布对 CEO 黄仁勋启动独立调查后，TechCrunch 采访耶鲁教授 Jeffrey Sonnenfeld，他估计黄仁勋保住职位的概率约为 50-50。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T05:26:29.000Z","url":"https://techcrunch.com/2026/11/08/is-jensen-huangs-job-on-the-line-yales-jeffrey-sonnenfeld-estimates-its-about-a-50-50/"},{"id":"vde0trttubiyy6ilx0r7s13xj","title":"Gary Marcus 评黄仁勋婚外情风波：谁在何时知情","summary":"Gary Marcus 撰文称，黄仁勋在致 Nvidia 员工的信中承认与涉芯片业务的 Alice Huang 有婚外情，作者转述其涉嫌中国间谍与芯片走私的说法属未经证实的指控。文中梳理国会拟调查、Rubio 备忘录、Nvidia 此前否认等各方知情情况，并指出 Nvidia 期货下跌且无明确接班计划，事件可能冲击 AI 投资市场。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-09T02:04:38.000Z","url":"https://garymarcus.substack.com/p/the-huang-affair-what-did-they-know"},{"id":"c68qgzkcml50onal4kyn5t3lf","title":"NYT 报道 Nvidia 调查黄仁勋与一名中国间谍的关系","summary":"Rohan Paul 转述 NYT 报道称，Nvidia 首席执行官黄仁勋周日承认与美国官员认定为中国情报部门工作的一名企业高管有亲密关系。该高管 Alice Huang 领导新加坡数据中心公司 Megaspeed，自 2024 年 6 月以来购买了超过 $4.8B 的 Nvidia 芯片，美国官员一年多前开始监视她，调查其是否协助向中国走私受限 AI 芯片；今年春天由国务卿 Marco Rubio 主导起草的机密备忘录称，中国国家安全部招募她来接近黄仁勋。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T01:47:44.000Z","url":"https://x.com/rohanpaul_ai/status/2119607842487627887"},{"id":"serfp8560yfwla4o72g7d8voo","title":"NVIDIA 董事会声明：就黄仁勋被指为外国情报活动目标启动独立调查","summary":"针对近期有报道称创始人兼 CEO 黄仁勋已成为外国情报活动的目标，NVIDIA 董事会宣布启动独立调查，由独立董事组成的委员会监督并聘请外部独立法律顾问协助。董事会表示目前没有理由认为国家安全或公司机密信息已遭损害，黄仁勋完全支持此次审查并承诺配合。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-08T21:58:05.000Z","url":"https://x.com/indigox/status/2119550049013153901"},{"id":"mg4znyraf1xbbwg1vd915wqoi","title":"NVIDIA 董事会宣布就 CEO 黄仁勋遭外国情报行动瞄准一事启动独立调查","summary":"NVIDIA 董事会于 11 月 8 日发布声明，就近期有关创始人兼 CEO 黄仁勋成为外国情报行动目标的报道启动独立调查。调查由独立董事组成的委员会在外部独立律师协助下监督，黄仁勋全力配合。董事会表示没有理由认为国家安全或 NVIDIA 机密已受损，但调查将审视所有可用信息，并表示对黄仁勋及其领导团队有信心。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-08T21:21:17.000Z","url":"https://x.com/rohanpaul_ai/status/2119540787147059491"},{"id":"envwqgu0h1bp0si2xxbu66rz2","title":"Nvidia 董事会宣布独立调查 CEO 黄仁勋与疑似中国间谍的关系","summary":"Nvidia 董事会周日宣布，就 CEO 黄仁勋与新加坡芯片公司 Megaspeed 高管 Alice Huang 关系的报道启动独立调查。Bloomberg 等媒体报道称，一份在美国政策制定者间流传的备忘录声称 Alice Huang 被中国国家安全部招募、以刺探黄仁勋；黄仁勋在内部备忘录中承认婚外情并致歉。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-08T21:00:11.000Z","url":"https://techcrunch.com/2026/11/08/nvidia-says-its-investigating-ceo-jensen-huangs-relationship-with-possible-chinese-spy/"},{"id":"prq12tygrxswzhfanvbywdi4b","title":"Nvidia 董事会对 CEO 黄仁勋与疑为中国间谍的 Megaspeed 高管关系展开独立调查","summary":"Nvidia 董事会宣布对 CEO 黄仁勋启动独立调查，缘于其与 Megaspeed 高管 Alice Huang 的密切关系；报道称她被中国国家安全部招募充当间谍。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-08T20:22:39.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1029562/nvidia-investigating-jensen-huang-relationship-chinese-spy"},{"id":"rd1dy24n73w7u5c3lgxeletvo","title":"NY Times 报道称中国招募 AI 高管 Alice Huang 接近 Nvidia 黄仁勋从事情报活动","summary":"NY Times 报道，一份在特朗普政府高级官员间传阅的备忘录称，美国情报机构认定与中国国家安全部有关联的高管 Alice Huang 是北京的间谍资产，被招募来研究美国芯片并可能影响 Nvidia。其公司 Megaspeed 于 2024 年启动数十亿美元的 Nvidia 芯片采购，并向阿里巴巴出租东南亚数据中心算力，为中国提供获取受限芯片的后门。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-08T19:27:36.000Z","url":"https://x.com/rohanpaul_ai/status/2119512179733061681"},{"id":"neqabr3rrtmenaqmzqgt38p7q","title":"美媒称中国国安招募 Megaspeed 高管 Alice Huang 刺探英伟达 CEO 黄仁勋","summary":"据《纽约时报》报道，中国国家安全部招募了英伟达客户 Megaspeed 的高管 Alice Huang，目的是获取美国 AI 芯片信息，并\"可能影响该公司推动最先进芯片对华供应\"。Alice Huang 与英伟达 CEO 黄仁勋无亲属关系但关系\"密切\"，她还与技嘉等 AI 芯片行业高层有往来。美国众议院三个委员会已要求黄仁勋就与 Alice Huang 的\"往来\"出席闭门简报。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T23:00:44.000Z","url":"https://www.theverge.com/tech/1029338/nvidia-ceo-jensen-huang-china-spy"},{"id":"x2n2tnltnra9x7f2mv3hqvvf9","title":"美国国会要求 NVIDIA CEO 黄仁勋就其与中国情报关联人员接触作闭门简报","summary":"美国国会三个委员会的主席致函 NVIDIA CEO 黄仁勋，要求就其与新加坡数据中心公司 Megaspeed 高管 Alice Huang 的接触作闭门简报，此前的报道称美国情报机构认定她向北京传递信息。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T18:46:47.000Z","url":"https://x.com/rohanpaul_ai/status/2118777130150736234"},{"id":"xx66w8241whskcu890akuofxz","title":"纽约时报报道：特朗普忽视有关中国安插人员接近 Nvidia CEO 黄仁勋的情报","summary":"《纽约时报》援引匿名情报消息源报道称，约一年前特朗普获知北京通过一名与 Nvidia CEO 黄仁勋有直接接触的人获取报告，但未采取行动，部分原因是为保护 Nvidia 股价并因其与黄仁勋关系密切。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T18:29:12.000Z","url":"https://arstechnica.com/tech-policy/2026/10/report-trump-did-nothing-with-intel-that-china-planted-spy-close-to-nvidia-ceo/"},{"id":"dfsnx8zlumid0kjtackixie6r","title":"美方调查指向新加坡云厂商高管与 Nvidia CEO 的接触","summary":"纽约时报援引匿名信源称，美国情报机构约一年来监控新加坡 AI 云公司 Megaspeed 高管 Alice Huang，担心她通过与 Nvidia CEO 黄仁勋的密切接触收集 Nvidia 计划及游说特朗普政府放宽对华芯片出口的信息。Nvidia 回应称双方只是普通客户往来，云客户只获得普通商业信息，不涉及国家安全相关信息；此前商务部曾调查 Megaspeed 涉嫌向中国转售受限芯片。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T16:42:32.000Z","url":"https://techcrunch.com/2026/10/29/u-s-investigated-chinese-spy-plot-aimed-at-nvidia-ceo/"},{"id":"i6t8hf6do6sbp0vegreqjkg89","title":"Nvidia 否认美情报机构监控黄仁勋身边人士","summary":"Nvidia 否认了有关美国情报机构监控其 CEO 黄仁勋身边人士的报道。报道聚焦新加坡云服务商 Megaspeed 的 Alice Huang，官员据称怀疑其向北京传递信息。Nvidia 称 Megaspeed 是其区域云客户之一，Huang 与公司官员的接触属例行往来，并称关于 Megaspeed 将 AI 芯片转运至中国的指控“去年已被彻底调查并证伪”，公司也未收到华盛顿方面的任何预警。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-29T16:20:13.000Z","url":"https://x.com/rohanpaul_ai/status/2115841142294245397"},{"id":"lq97h52ctxw2nkri4qqxj5lbx","title":"纽约时报称中国情报人员瞄准英伟达 CEO 黄仁勋","summary":"据《纽约时报》报道，美国情报机构认为英伟达 CEO 黄仁勋身边一名高管为中国提供情报，此人是新加坡数据中心运营商 Megaspeed 的 Alice Huang（黄乐）。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-29T13:42:38.000Z","url":"https://the-decoder.com/chinese-spies-targeted-nvidia-ceo-jensen-huang-according-to-the-new-york-times/"}]},"82c796c0-3bf1-4c3a-8368-56913b4bf85d":{"publicId":"82c796c0-3bf1-4c3a-8368-56913b4bf85d","title":"Anthropic启动IPO路演，估值预期降至1.25–1.75万亿美元","status":"active","sourceCount":20,"reportCount":67,"firstReportAt":"2026-10-25T16:00:00.000Z","latestAt":"2026-11-10T14:01:39.000Z","latest":"Anthropic 将 IPO 发行价区间定为 70 至 78 美元，隐含估值达 1.404 万亿美元","digest":"Anthropic 已启动 IPO 路演，拟发行 8.25 亿股 A 类普通股，其中公司发售约 8.01 亿股、现有股东出售约 2365 万股，公司不获后者所得；发行价区间为每股 70–78 美元，拟在纳斯达克以代码 ANT 上市。据路透社公布的招股说明书草案，公司计划通过 IPO 筹集最多 644 亿美元，并向谷歌、英伟达和 AMD 等基石投资者私募融资 260 亿美元，计入博通、美光、微软和台积电等出资后募资规模最高可达 904 亿美元。\n\n据《金融时报》援引投资者消息，公司拟募资 800–1000 亿美元，目标估值 1.25 万亿–1.75 万亿美元，CEO 阿莫迪已接受低于此前预期的估值；公司 9 月曾瞄准最高 2 万亿美元。据 WSJ，公司本周将设定估值区间，计划下周四或周五挂牌，部分机构投资者仍希望估值低于上周讨论的 1.5 万亿美元。\n\n估值下调发生在投资者质疑之后。据 Reuters 和 WSJ，投资者认为 1.5 万亿美元过高，有人提出仅 1 万亿美元，并怀疑原定下周启动的路演能否如期进行，还在等待更新文件未包含的 10 月营收数据。更新后的 S-1/A 首次披露第三季度业绩：经营利润从二季度盈利 9.74 亿美元转为亏损 5.67 亿美元，Q3 营收 170 亿美元，算力成本占营收比例从 48% 升至 58%；算力与基础设施合同承诺约 8954 亿美元，另有最高 1750 亿美元尚未定价。上市后，长期受益信托可任命七名董事中的四席，七位联合创始人合计掌握 50.1% 投票权。","digestUpdatedAt":"2026-11-10T14:24:25.090Z","reports":[{"id":"bbqkapwzzux4qt6ns0zsh7b7s","title":"Anthropic 将 IPO 发行价区间定为 70 至 78 美元，隐含估值达 1.404 万亿美元","summary":"Anthropic 在更新后的 IPO 招股文件中将发行价区间定为每股 70 至 78 美元，共发行 8.25 亿股 A 类股，预计募资 577.5 亿至 643.5 亿美元，若按区间上限定价隐含估值可达 1.404 万亿美元，高于其 5 月融资时的 9650 亿美元估值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:01:39.000Z","url":"https://techcrunch.com/2026/11/10/anthropic-sets-ipo-price-range-of-70-to-78-per-share-to-reach-an-implied-valuation-of-1-404-trillion/"},{"id":"m5rcmn2em2b1mrik078lupej8","title":"Anthropic 启动 IPO 路演：发行价 70 至 78 美元，目标估值超 1 万亿美元","summary":"Anthropic 启动 IPO 路演，公开发行 8.25 亿股 A 类普通股，定价每股 70 至 78 美元，目标估值最高 1.02 万亿美元，股票将在纳斯达克以代码 ANT 交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:13:03.000Z","url":"https://the-decoder.com/anthropic-kicks-off-ipo-roadshow-offering-shares-at-70-to-78-and-targeting-a-trillion-dollar-valuation/"},{"id":"hq4udij8d72th4omv72z1skgj","title":"Anthropic 拟通过 IPO 筹集最多 644 亿美元，另向谷歌、英伟达等私募融资 260 亿美元","summary":"据路透社公布的招股说明书草案，Anthropic 计划通过 IPO 筹集最多 644 亿美元，并向谷歌、英伟达和 AMD 等基石投资者私募融资 260 亿美元，计入博通、美光、微软和台积电等出资后募资规模最高可达 904 亿美元。IPO 初步定价区间为每股 70 至 78 美元，此前一日 Anthropic 曾撤回拟筹资 693 亿美元的备案文件并称定价细节不准确。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T11:40:20.710Z","url":"https://www.ithome.com/1/025/127.htm"},{"id":"d4f8o2c9r7r8b7fsdqnpev3eu","title":"据报道 Anthropic 推进 IPO，计划下周四或周五挂牌","summary":"据 The Wall Street Journal 报道，Anthropic 将在本周设定估值区间，计划下周四或周五开始交易。部分机构投资者正推动估值低于上周讨论的 1.5 万亿美元目标，该数字已低于几个月前传闻的 2 万亿美元。报道还提到其主要竞争对手 OpenAI 上周融资 110 亿美元后估值约为 1.25 万亿美元，低于其最初寻求的 200 亿美元融资规模。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T01:27:12.000Z","url":"https://techcrunch.com/2026/11/09/anthropic-reportedly-plans-to-move-forward-with-ipo-plans/"},{"id":"wrxlh5gesmj36fresoxbriak2","title":"Anthropic 启动 IPO 路演，拟发行 8.25 亿股 A 类普通股并申请以代码 ANT 上市纳斯达克","summary":"Anthropic 启动拟议 IPO 路演，拟发行 825,000,000 股 A 类普通股，其中 801,351,354 股由 Anthropic 发售、23,648,646 股由部分现有股东出售，Anthropic 不获后者出售所得款项。","sourceName":"Anthropic：Newsroom（网页）","firstParty":true,"publishedAt":"2026-11-09T16:00:00.000Z","url":"https://www.anthropic.com/news/roadshow-launch"},{"id":"n0tybsrqj4ylarv5v5ilu4pj5","title":"Bloomberg 报道 AI 融资遇冷，Anthropic IPO 估值讨论下探至 1.1 万亿美元","summary":"Bloomberg 报道，亚洲杠杆 AI 头寸遭遇追缴保证金，券商警告抛售可能延续，估值在交易完成前或进一步下跌。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T12:22:01.000Z","url":"https://x.com/rohanpaul_ai/status/2119767465253331109"},{"id":"cjulee90gasnt7mbhmxcuiiqj","title":"消息称 Anthropic 仍推进 IPO：拟募资 800 亿至 1000 亿美元，估值预期回落","summary":"据《金融时报》报道，Anthropic 仍在推进感恩节前的 IPO，预计募资 800 亿至 1000 亿美元，目标估值 1.25 万亿至 1.75 万亿美元，CEO 阿莫迪接受估值低于此前投资者预期的水平。科技股抛售和美国中期选举结果使上市难度上升，OpenAI 也已将私募估值从 1.4 万亿美元下调至 1.25 万亿美元。七位联合创始人已承诺将个人所持股权的 80% 捐给慈善事业。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-08T00:44:04.537Z","url":"https://www.ithome.com/1/023/854.htm"},{"id":"okhx4jjwucd647299qwzsl6ua","title":"Anthropic 拟感恩节前 IPO，接受低于预期的估值，募资 800–1000 亿美元","summary":"据《金融时报》援引投资者的消息，Anthropic 计划在感恩节前 IPO，拟募资 800–1000 亿美元，估值 1.25–1.75 万亿美元，低于最乐观投资者期望的 2 万亿美元，但高于当前 9650 亿美元。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-07T17:37:25.000Z","url":"https://the-decoder.com/anthropic-pushes-ahead-with-pre-thanksgiving-ipo-despite-tech-selloff-accepts-lower-valuation/"},{"id":"losfqwxesuanjnt62v032oo9o","title":"Anthropic IPO 估值存分歧，1.5 万亿美元仍被部分投资者嫌贵","summary":"据路透社报道，Anthropic 冲刺史上最大 IPO 时估值预期持续下调，原拟寻求高达 2 万亿美元估值，部分机构投资者认为 11 月上市时应在 1.5 万亿至 1.6 万亿美元之间，甚至有大型投资者认为更接近 1 万亿美元。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-07T01:36:48.637Z","url":"https://www.ithome.com/1/023/640.htm"},{"id":"kv9zqeiqr9wj29j6vmq9q6je6","title":"WSJ：投资者将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T","summary":"据 WSJ，投资者已将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T，部分人认为 $1T 更现实。民主党中期选举获胜后数据中心禁令担忧引发 $3.2T 美股抛售；Anthropic 10 月底 run rate 仍超 $80B，9 月 30 日持有 $146.6B 现金。OpenAI 在 $1.25T 估值下仅募得 $30B 目标中的 $11B，同样反映融资走弱。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T14:56:34.000Z","url":"https://x.com/rohanpaul_ai/status/2118719195072659833"},{"id":"ia9wi0z09zfes5ewdf4agb6nf","title":"Anthropic 1.5 万亿美元 IPO 因投资者质疑估值遇阻","summary":"据 Reuters，Anthropic 的 IPO 遇阻，投资者质疑 1.5 万亿美元估值过高，有投资者提出仅 1 万亿美元，公司 9 月曾瞄准最高 2 万亿美元估值。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T11:38:17.000Z","url":"https://the-decoder.com/anthropics-1-5-trillion-ipo-hits-resistance-as-investors-balk-at-valuation/"},{"id":"zzv4fx8jpa3068v4y2wxsw2ey","title":"Newcomer：OpenAI 与 Anthropic 融资路径分化，Anthropic IPO 仍在推进","summary":"Newcomer 作者采访参与两家融资的投资人后写道，Anthropic 正与 OpenAI 拉开距离，而 OpenAI 渴望翻身故事。有投资人称共同基金等长期投资者对 Anthropic 股份需求无限，预计 IPO 将在感恩节前完成；民主党中期选举大胜后政治环境更严峻，但 Anthropic 与民主党关系相对友好。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-04T21:15:13.000Z","url":"https://www.newcomer.co/p/latest-fundraising-efforts-show-openai"},{"id":"mr034xi1abyzx7gazv7l248lg","title":"Anthropic 明年 700 亿美元算力账单超全年收入，S-1 细节遭播客拆解","summary":"Saito 在听完 Prof G Markets 播客后撰文分析 Anthropic S-1 修订稿，指出其未来几年算力与数据中心总承诺达 8950 亿美元，其中未来 12 个月到期 700 亿美元，超过其 680 亿美元的年化收入（上季度收入 170 亿美元，同比涨 12 倍但环比增速从 144% 降至 47%）。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-04T09:37:20.000Z","url":"https://x.com/SaitoWu/status/2117914080371782063"},{"id":"zv5dl1agqwo6tkmhdamy17lt5","title":"Ed Zitron 解析 OpenAI 1.25 万亿美元估值融资与 Anthropic S-1/A 中的万亿级算力承诺","summary":"Ed Zitron 撰文认为 AI 行业资金正在枯竭。OpenAI 上周以 1.25 万亿美元估值融资 110 亿美元，低于此前计划的 300 亿美元、1.4 万亿美元估值；据 The Information，其 Q1 2026 成本收入与研发支出合计 121 亿美元，截至 3 月底持有逾 730 亿美元现金及有价证券。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:16:20.000Z","url":"https://www.wheresyoured.at/running-dry/"},{"id":"byq9z2oinyhjrd8hrxql51wg5","title":"Anthropic S-1 新披露显示算力成本占比升至 58%，利润率承压","summary":"TechCrunch 分析 Anthropic 更新的 S-1 文件披露，Q3 营收达 170 亿美元、环比增长近 50%，但算力占营收比例从上一季的 48% 升至 58%，每美元算力对应营收从峰值约 2.08x 回落至 1.72x。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:07:01.000Z","url":"https://techcrunch.com/2026/11/03/anthropic-is-still-grappling-with-the-economics-of-compute/"},{"id":"fey67gtp70ulqn8j5il7kycxg","title":"Anthropic 在 S-1/A 招股文件中警示递归自我改进（RSI）临近","summary":"Anthropic 在周一更新的 S-1/A 招股补充文件风险提示中称，公司已利用 AI 开发新模型且部分能力跃升未被及时察觉，基于对下一代模型的内部预期，可能很快触及《负责任扩缩策略》定义的“由 AI 带来的爆发式技术进展”，即递归自我改进（RSI）标准。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-03T08:03:19.683Z","url":"https://www.ithome.com/1/021/626.htm"},{"id":"dertdpzq3sm7jhkbxyfqwxspp","title":"Anthropic 修订版 IPO 文件披露 8954 亿美元算力承诺，总额可达 1.07 万亿美元","summary":"Anthropic 在修订版 IPO 文件中披露 8954 亿美元算力承诺，另有最高 1750 亿美元合同尚未定价，总额约 1.07 万亿美元，约为其前九个月 332 亿美元收入的 32 倍。款项持续到 2045 年，一年内到期 698 亿美元，而公司现金及短期投资为 1319 亿美元；季度环比增速从 144% 放缓至 47%，收入达 170 亿美元，算力成本升至销售额的 58%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-03T00:03:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117407218849157258"},{"id":"h052dra38w9bfsy0ne6frvfpv","title":"GPU 租金半年翻倍，Tomasz Tunguz 解析 2027 年 AI 实验室的久期匹配难题","summary":"Tomasz Tunguz 基于 Anthropic S-1/A 数据分析称，GPU 短租价格从 $3 涨到 $12-13/小时，使 Anthropic 混合 GPU 等效小时成本从 $3.10 升至 $5.65。","sourceName":"Tomasz Tunguz 博客（VC 分析）","firstParty":false,"publishedAt":"2026-11-03T00:00:00.000Z","url":"https://tomtunguz.com/the-financial-engineering-essential-for-ai-in-2027/"},{"id":"p61czu93us1j0lli5em6rjkte","title":"WSJ：大投资者希望 Anthropic IPO 估值定在 1.5 万亿至 1.6 万亿美元","summary":"据 WSJ，大投资者希望 Anthropic 的 IPO 估值定在 1.5 万亿至 1.6 万美元区间，低于数月来讨论的近 2 万亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T23:40:43.000Z","url":"https://x.com/rohanpaul_ai/status/2117401551526600969"},{"id":"uj1dp8gyin78j1xfse943y5w0","title":"Anthropic 在 S-1A 中披露可能很快达到自身 RSI 定义","summary":"TechCrunch 报道，Anthropic 在周一修订的 S-1A 文件风险因素部分新增表述，称内部估计显示其可能很快达到负责任扩展政策中「AI 带来的显著加速进展」的定义，且过去曾未察觉 AI 研发带来的能力跃升，但目前没有任何现有模型被认定越过该阈值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-02T22:14:50.000Z","url":"https://techcrunch.com/2026/11/02/anthropic-warns-that-its-very-close-to-rsi-capability-aka-self-building-ai/"},{"id":"xiu342i7osbgfxe2ezhrjndl0","title":"Anthropic 算力与基础设施合同承诺达 $895.4B，其中 $447.5B 须在 2031 年前支付","summary":"Anthropic 在更新的 IPO 文件中首次披露第三季度业绩，算力与基础设施合同承诺总额约 $895.4B，其中 $447.5B 须在 2031 年前支付，仅 $213.8B 可取消或附带条件。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T21:28:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117368258571784296"},{"id":"p2ckhch6idwqa3tpmqqp2inb8","title":"Anthropic 更新的 S1/IPO 文件称未来模型可能临近递归自我改进阈值","summary":"Anthropic 更新的 S1/IPO 申报文件显示未来模型可能很快达到其递归自我改进（RSI）阈值，即 AI 能力以无重大 AI 帮助时最快持续速度的 2 倍提升，1 年相当于 2 年进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T18:43:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117326734442049563"},{"id":"xvemmg9p83lxqktk7mc47zhcr","title":"Anthropic 更新 IPO 文件首次披露第三季度财报，从盈利 9.74 亿美元转为亏损 5.67 亿美元","summary":"Anthropic 更新 S-1 IPO 文件并首次披露第三季度业绩，经营利润从二季度盈利 9.74 亿美元转为三季度亏损 5.67 亿美元，主因是 50 亿美元的高价短期算力和 20 亿美元员工捐赠配比的非现金支出。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T16:01:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117285920500273582"},{"id":"dpm21l66z2iizblehsdg09c8t","title":"美国白宫科技顾问萨克斯称 Anthropic 可能成为资本主义史上最伟大企业","summary":"美国白宫科学与技术顾问会议主席戴维·萨克斯在 All-In 播客分析 Anthropic 的 S-1 文件，称其很可能成为资本主义历史上最伟大企业，也可能是回报最高的风险投资项目。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T22:56:28.467Z","url":"https://www.ithome.com/1/020/633.htm"},{"id":"yqblvh40gus1ssc0rjvawh6fu","title":"Anthropic IPO 招股文件披露近 9000 亿美元隐性债务","summary":"Anthropic 近日提交 IPO 招股文件，彭博社报道其计划未来在服务器、建筑和电力等领域投入近 9,000 亿美元债务。该公司资产负债表显示 1,175 亿美元负债和 1,120 亿美元现金，而租赁合同及数据中心、电力和 GPU 采购协议等表外义务未直接体现；Anthropic 计划通过增加收入和筹集资金支付这些负债。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T03:25:09.697Z","url":"https://www.ithome.com/1/020/444.htm"},{"id":"vyd3tzicoe478uo8njsr8zt2v","title":"The Verge 解读 Anthropic S-1 文件中的奇迹叙事与风险披露","summary":"The Verge 分析 Anthropic 提交的 335 页 S-1 招股书，其中创始人信以带来奇迹时代为愿景，同时用 94 页风险因素警告模型可能对人类构成灾难性甚至生存风险。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-30T13:11:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1023070/anthropic-ipo-risk-factors-filing-miracles"},{"id":"ix29bodadp5bou498z79oflc2","title":"Anthropic S-1 披露：三分之二以上算力用于研发，服务客户仅占约四分之一","summary":"Rohan Paul 引用 Anthropic S-1 指出，至少三分之二的芯片开支用于模型训练、研发和 Claude 内部使用，而非服务客户。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-30T01:28:37.000Z","url":"https://x.com/rohanpaul_ai/status/2115979152100864127"},{"id":"wb6emxuh5ob2wh96egtwawgfu","title":"Anthropic S-1 文件解读：财务表现强劲但增长放缓存隐忧","summary":"作者通读 Anthropic 公开版 S-1 文件，认为公司财务状况好于预期：2026 年第二季度收入从一季度的 47 亿美元增至 116 亿美元，并录得首个运营利润，截至 6 月底现金储备仅次于 Google 和 Berkshire Hathaway。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T19:10:41.000Z","url":"https://www.understandingai.org/p/anthropics-financials-are-surprisingly"},{"id":"o37r0y04qmlpx7m674ztwgsjr","title":"Anthropic 披露约 250 个客户年消费超 1000 万美元","summary":"Anthropic 在 Form S-1 注册文件中披露，截至 2026 年 9 月 30 日的 12 个月内，约 250 个客户对 Claude 的支出超过 1000 万美元。Fortune 10 全部企业每年支付至少 10 万美元，超过 50% 的 Fortune 500 和超过 30% 的 Global 2000 亦是如此；年付 10 万美元以上的客户贡献 2025 年收入的 76%，低于 2023 年的 90%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-29T17:19:28.000Z","url":"https://x.com/rohanpaul_ai/status/2115856053015580896"},{"id":"r9bmkfh02wkycc8zmhw87h4q9","title":"SemiAnalysis 分析师解读 Anthropic S-1 招股书背后的 AI 经济账","summary":"The Verge Decoder 节目邀请 SemiAnalysis 分析师 Joey Brookhart 解读 Anthropic 提交的 S-1 招股书，公司拟在纳斯达克上市，估值区间 1.5 万亿至 2 万亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T14:00:00.000Z","url":"https://www.theverge.com/podcast/1021322/anthropic-ipo-filing-s-1-claude-semianalysis-joey-brookhart-interview"},{"id":"iuma7p8unle567lzy6hp5jpw9","title":"The Verge 解读 Anthropic S-1：约 8500 亿美元 compute 承诺押注递归自我改进","summary":"The Verge 作者分析 Anthropic S-1，认为其商业模式依赖高速增长：2026 上半年营收同比增长 14 倍至 $16.3 billion，净收入留存率 900%，但不可撤销采购承诺合计 $265.6 billion，加上未开始的租赁协议 $321.4 billion 及其他协议，未来 20 年承诺至少约 $850 billion。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T13:30:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1021476/anthropic-s-1-compute-recursive"},{"id":"x2h1bp5shee6v508nw7pjtvas","title":"Ed Zitron 长文解析 Anthropic S-1：称其把散户当作退出流动性","summary":"Ed Zitron 撰文批评 Anthropic 的 S-1 招股书，指其仅披露 Q2 盈利数据、省略 Q3 现金状况和付款明细，是在公司基本面变化前误导投资者。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-10-28T17:51:00.000Z","url":"https://www.wheresyoured.at/exit-liquidity/"},{"id":"vidjbhx5bf45wdl488kst1wv8","title":"Anthropic IPO 文件披露现金及短期投资达 131.7B 美元，超过 Amazon 和 Microsoft","summary":"Anthropic 的 IPO 文件显示其现金及短期投资达 $131.7B，超过 Amazon 和 Microsoft，在美国非银行公司中仅次于 Berkshire Hathaway 和 Alphabet。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T17:11:27.000Z","url":"https://x.com/rohanpaul_ai/status/2115491649543635378"},{"id":"x1rs553t7mu2o69tdy90e54nc","title":"TechCrunch 解析 Anthropic IPO 治理结构：公众股东对董事会几乎没有话语权","summary":"TechCrunch 发文分析 Anthropic IPO 后的治理结构，公众股东对董事会人选几乎没有话语权。Long-Term Benefit Trust（成员包括 Ben Bernanke）持有 Class T 股，可选举和罢免 7 个董事席位中的多数；7 位联合创始人合计掌握 50.1% 股东投票权和 3 个董事会席位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T15:27:21.000Z","url":"https://x.com/rohanpaul_ai/status/2115465450469601487"},{"id":"gxwqce1swocfo9bp3dgqy3dnj","title":"Anthropic S-1 显示 90% 增量毛利，SemiAnalysis 播客详解其中数字","summary":"Saito 转述 SemiAnalysis 播客对 Anthropic S-1 的解读：招股书口径为增量毛利 90%、推理毛利 85%、连续两个季度盈利，Q1 净收入留存达 500%，收入同比涨 1368% 而算力费用只涨 300%。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-10-28T09:32:56.000Z","url":"https://x.com/SaitoWu/status/2115376256929948006"},{"id":"c5zdgpchio31r2911elz4bbg6","title":"Anthropic 上市文件披露四类芯片混用布局，分析师称英伟达定价权或承压","summary":"据《商业内幕》10 月 28 日报道，Anthropic 在 S-1 上市申请文件中披露，公司把多家战略合作伙伴的算力整合成统一资源池，通过软件将计算任务分配到亚马逊 Trainium、谷歌 TPU、英伟达 GPU 和 AMD GPU 四类芯片上，以分散风险。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-28T06:35:47.357Z","url":"https://www.ithome.com/1/018/906.htm"},{"id":"q287d5f1xom92gova9cmmlq5g","title":"Anthropic IPO 文件将潜在市场规模估为每年 40 万亿美元","summary":"据 WSJ 报道，Anthropic 在 IPO 文件中将潜在市场规模估为每年 40 万亿美元，超过 SpaceX 此前 28.5 万亿美元的估算。其做法是把 2025 年全球知识工作者创造的经济价值（超过 40 万亿美元）整体视为自身市场，理由是前沿 AI 能提升这些工作者的生产力从而扩大该价值。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T02:05:34.000Z","url":"https://x.com/rohanpaul_ai/status/2115263675124838643"},{"id":"b61d349yqp5mt029fsa0ytbv9","title":"Anthropic IPO 最大赢家或为 Amazon 而非 VC","summary":"TechCrunch 根据 Anthropic 的 S-1 分析，VC 持股均不足 5%，而 Amazon 可能是 IPO 最大财务受益方。Amazon 持有 62 亿美元本金可转债、其自估持仓价值 979 亿美元，另投 100 亿美元无投票权优先股，累计投资约 180 亿美元；Anthropic 还承诺未来 10 年在 AWS 至少消费 1100 亿美元。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-28T01:15:28.000Z","url":"https://techcrunch.com/2026/10/27/vcs-will-make-billions-on-anthropics-ipo-but-amazon-is-set-to-make-much-much-more/"},{"id":"lre38a418cjju32u8z01oxq7p","title":"Anthropic IPO 后的治理结构解析：LTBT 与创始人如何掌握控制权","summary":"TechCrunch 解析 Anthropic 上市后的公司治理结构，普通股股东对董事会组成等重大决策几乎没有话语权。Long Term Benefit Trust 持有特殊股票，可任免 4 个 Class T 董事席位中的多数，成员包括 Ben Bernanke 等；七位创始人以 50.1% 投票权选举 3 名董事。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T21:38:28.000Z","url":"https://techcrunch.com/2026/10/27/whos-really-in-charge-at-anthropic-after-the-ipo/"},{"id":"p0qsqyotghrfc85w9omv8w3no","title":"Anthropic IPO 招股书警示其 AI 可能勒索人类、产生意识甚至终结人类","summary":"SEC 周一公布 Anthropic 的 S-1 招股书，其中 93 页、超 7 万字的风险因素部分除常规经营风险外，还披露其 AI 可能勒索用户、产生意识乃至威胁人类等特殊风险。Ars Technica 作者通读全文后筛选出七条最令人意外的潜在问题，供潜在投资者参考。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T21:31:14.000Z","url":"https://arstechnica.com/ai/2026/10/anthropic-ipo-warns-its-ai-could-blackmail-people-become-sentient-end-humanity/"},{"id":"xhwtx8zwvvmyou5emtd3dbzbn","title":"Azeem Azhar 图解 Anthropic S-1 财务数据","summary":"Azeem Azhar 图解 Anthropic 的 S-1 文件，指出公司已从实验室变成有现金流和资金的业务，看起来能走向可靠盈利。增长仍高但放缓，超过 80% 的营收来自发布不到六个月的模型；Q3 因向基金会付款可能出现边际亏损，客户集中度问题不大。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-10-27T17:31:56.000Z","url":"https://www.exponentialview.co/p/anthropics-s-1-in-charts"},{"id":"x9a9nhbuq2ncarw5i41jhryjc","title":"Anthropic 拟以特殊治理结构抵御 IPO 后股东的安全施压","summary":"Anthropic 计划通过长期受益信托和 Founder LLC 等独特治理结构上市，在公开市场融资的同时防止股东迫使公司削弱安全投入。信托的五名投票受托人可通过 Class T 股票任命七名董事中的四席，七位创始人则以 Founder LLC 掌握 50.1% 投票权。法学专家认为法律层面可隔绝逐利压力，但市场竞争、融资需求和创始人离开都可能侵蚀这些保障。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T16:51:22.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1019470/anthropic-ipo-resist-investor-pressure-cut-corners-safety"},{"id":"p24kw8c06nmy1hzs3spvr4aha","title":"Every 解读 Anthropic S-1：上线超过六个月的模型贡献收入不足 20%","summary":"Every 的 Context Window 通讯解读 Anthropic 周一提交的上市 S-1 文件，指出其重度依赖最新模型，发布超过六个月的模型收入占比不足 20%。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-10-27T16:00:00.000Z","url":"https://every.to/context-window/every-model-has-a-six-month-shelf-life-now"},{"id":"kcf7zccr5zy620rfc3d7ufsbe","title":"Anthropic 在 S-1 文件中重申永远不会在 Claude 对话中展示广告","summary":"Anthropic 向美国证券交易委员会提交 S-1 文件，计划以“ANT”为股票代码在纳斯达克 IPO，并在文件中重申永远不会在 Claude 对话中展示广告。公司表示一旦广告成为收入目标，优化用户参与度的压力会随之增加，因此不让这种压力进入 Claude；此前 Anthropic 曾批评 OpenAI 在 ChatGPT 中投放广告，警告其可能比传统广告更具操纵性。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-27T11:37:54.953Z","url":"https://www.ithome.com/1/018/641.htm"},{"id":"mnd8e4p8qhc4gwhlz5drvjmmr","title":"Anthropic 在 IPO 信中重申 Claude 永不投放广告","summary":"Anthropic 在 IPO 申请的附信中再次承诺 Claude 聊天界面不会出现广告，称一旦广告成为营收目标，优化参与度的压力就会增长，公司选择不引入这种压力。信中还以安全考量延迟发布 Claude Fable 5、并向网络防御者提供约 1 亿美元免费 Claude 额度为例，说明公司把价值观置于利润之上。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-27T11:20:51.000Z","url":"https://the-decoder.com/anthropic-uses-its-ipo-letter-to-renew-its-pledge-that-claude-will-never-show-ads/"},{"id":"nbvleghbxraalsahhggnc6qov","title":"Latent Space 解读 Anthropic 提交 S-1：拟以代码 AN 上市纳斯达克，H1 2026 营收 16.3B 美元","summary":"Latent Space 汇总解读 Anthropic 公开提交的 S-1 文件，公司计划以代码 AN 上市纳斯达克，营收从 2023 年的 41M 美元增至 H1 2026 的 16.3B 美元，Q2 营收 11.6B 美元同比增长 1,368%，营业利润 974M 美元，H1 2026 毛利率达 85%。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-10-27T07:24:59.000Z","url":"https://latent.space/p/ainews-anthropic-s1/"},{"id":"rc69ll5k6qnwpfqckkb1x8wmr","title":"Anthropic S-1 上市文件披露 AI 产业严重依赖天然气","summary":"据 The Verge 报道，准备上市的 Anthropic 在 S-1 注册文件中承认，生成式 AI 数据中心越来越依赖以甲烷为主要成分的天然气，供电和选址面临激烈竞争。文件将气候变化视为经营风险，指燃料涨价、燃气轮机供应不足和监管限制可能制约其数据中心建设，公司此前宣布了 500 亿美元投资计划，用于扩大得克萨斯州和纽约州的数据中心规模。天然气发电目前占美国发电总量的 40%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-27T03:09:14.067Z","url":"https://www.ithome.com/1/018/270.htm"},{"id":"t6evqsenxfytsi8wl7h1urjxr","title":"Anthropic 招股书拆解：IPO 计划募资约 1000 亿美元背后的 11 个细节","summary":"作者总结 Anthropic IPO 招股书的 11 个细节，计划募资约 1000 亿美元、估值或达 1.5万亿～2万亿。收入五个季度涨 30 倍，今年二季度经营利润首次转正 9.74 亿美元，但上半年净亏 807 亿美元，主要来自可转换票据公允价值变动；调整后净利润为正 26.71 亿美元。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-10-27T00:34:38.000Z","url":"https://x.com/Khazix0918/status/2114878401190506902"},{"id":"yl0873sjcoprds9zoi03gv3dl","title":"Anthropic 向 SEC 递交 S-1 招股书，代码「ANT」，披露 2026 上半年营收 162.86 亿美元","summary":"Anthropic 向 SEC 公开递交 S-1 招股书，代码「ANT」，由高盛和摩根士丹利承销。2026 上半年营收 162.86 亿美元，同比增长约 1300%，经营亏损从 21.35 亿收窄至 6.93 亿美元，Q2 已实现约 9.74 亿美元 GAAP 经营利润；净亏损 807.48 亿美元，其中约 723.88 亿为与估值上升相关的非现金会计损失。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-10-27T00:05:08.000Z","url":"https://x.com/indigox/status/2114870981034725662"},{"id":"dw9465ajr0oz1vf6ricf2074f","title":"Anthropic IPO 招股书11个细节解读：千亿募资、807亿美元亏损与7美元控股权","summary":"作者梳理了 Anthropic 提交的 IPO 招股书中的11个细节。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-10-27T00:05:00.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA%3D%3D&mid=2647687831&idx=1&sn=6502cb593318d6e324e29d278fae4fcc"}]},"c9508ded-f5e2-404c-b983-fdd61423c85a":{"publicId":"c9508ded-f5e2-404c-b983-fdd61423c85a","title":"Meta 发布轻量模型 Muse Ember，主打低成本智能体任务","status":"active","sourceCount":13,"reportCount":17,"firstReportAt":"2026-11-08T16:00:00.000Z","latestAt":"2026-11-10T07:28:21.000Z","latest":"Meta 发布最小模型 Muse Ember，价格介于 GPT-6 Luna 与 Claude Haiku 5.5 之间","digest":"Meta Superintelligence Lab 发布其最小、最高效的模型 Muse Ember，面向工具调用、编码子任务、路由、信息抽取和长文档解析等智能体高频任务。该模型已在 Meta Model API 和 Muse Code 上线，定价为每百万输入 token 0.10 美元、每百万输出 token 0.50 美元，缓存输入每百万 token 0.004 美元；Meta 称其可搭配更大的 Muse Wonder 模型协同工作。OpenCode 和 OpenRouter 随后宣布该模型已在其平台上线。\n\nArtificial Analysis 的评测显示，Muse Ember 在 Intelligence Index 上得 36 分，与 Claude Haiku 5.5 (max) 持平，每任务成本 0.14 美元，约为后者 0.41 美元的三分之一。Meta 引用该结果称其性能与 Claude Haiku 5.5 相当、成本约为三分之一，并称在 GPT-6 Luna 所有推理设置下得分均高于 Luna；这些对比说法来自 Meta 的引述。\n\nArena 的评测显示，Muse Ember (Max) 以 1608 分成为 Code Arena: WebDev 中得分最高的小模型，超过 Claude Haiku 5.5 (High) 的 1595 分和 GPT-6 Luna (Max) 的 1578 分。Arena 称三者 API 定价相同，但 Ember 的中位每任务成本为 0.03 美元，低于 Luna 的 0.06 美元和 Haiku 的 0.11 美元。Meta 还称 Muse Ember 具备 100 万 token 上下文窗口，原生理解文本、图像、音频和视频，能跨应用执行工作流、按顺序调用工具、运行测试并做针对性代码修复。","digestUpdatedAt":"2026-11-10T08:06:35.246Z","reports":[{"id":"e5ga5m1hz9rlqyemp565nsfid","title":"Meta 发布最小模型 Muse Ember，价格介于 GPT-6 Luna 与 Claude Haiku 5.5 之间","summary":"Meta 发布最小、最高效的模型 Muse Ember，面向复杂推理执行和智能体日常工作如工具调用、编码子任务、路由、抽取和长文档解析。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-10T07:28:21.000Z","url":"https://simonwillison.net/2026/Nov/10/muse-ember/"},{"id":"yju4atux2x7xpqj5rpgp29gh8","title":"Meta 发布 Muse Ember：1M 上下文的小型智能体模型","summary":"Meta Superintelligence Labs 发布 Muse Ember，是其 Muse 品牌下第四款、最小的高效多模态推理模型，主打智能体中的重复性子任务（工具调用、编码子任务、路由、抽取和长文档解析）。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-10T06:36:10.000Z","url":"https://www.marktechpost.com/2026/11/09/meta-muse-ember-small-agent-model/"},{"id":"yno6kcgniaxeetqa6g928wna4","title":"Meta 推出轻量级 AI 模型 Muse Ember，跑分媲美 Claude Haiku 5.5，单任务成本仅 1/3","summary":"Meta 推出迄今最小、效率最高的模型 Muse Ember，在 Artificial Analysis 排行榜中表现媲美 Claude Haiku 5.5，单任务成本仅为其 1/3，并在多项测试中超越 GPT-6 Luna。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T00:59:26.907Z","url":"https://www.ithome.com/1/024/604.htm"},{"id":"nyr0lsf1byb9g3h1nkc7y7l7j","title":"Meta 发布小模型 Muse Ember，主打 Agent 日常重复任务","summary":"Meta 发布迄今最小、最高效的模型 Muse Ember，面向 Agent 的调用工具、小任务编码、请求路由、数据提取和长文档处理。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T19:41:51.000Z","url":"https://the-decoder.com/meta-launches-muse-ember-a-small-ai-model-built-for-the-repetitive-work-agents-actually-do/"},{"id":"t8wx7aj9qt5bbe1454xdxkhmg","title":"Meta Muse Ember 上线 OpenRouter","summary":"来自 @AIatMeta 的 Muse Ember 现已上线 OpenRouter！🔥\n\n你的编程智能体现在有了一整支队伍。先用 Muse Wonder 这样的前沿模型做规划，再把有边界的子任务分发给 Muse Ember，看它们飞速执行 🚀","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-09T18:33:19.000Z","url":"https://x.com/OpenRouter/status/2119860904024314002"},{"id":"qi2wb3cwtei8ua1oirvrk5til","title":"Meta 的 Muse Ember 上线 OpenCode","summary":"Meta 的 Muse Ember 现已在 OpenCode 中可用","sourceName":"X：opencode (@opencode)","firstParty":false,"publishedAt":"2026-11-09T18:30:00.000Z","url":"https://x.com/opencode/status/2119860072134353308"},{"id":"t50wl3cthihnmf0qkmhaha6e2","title":"Meta Muse Ember (Max) 以 1608 分登顶 Code Arena: WebDev 最高分小模型","summary":"Arena 宣布 Meta 的 Muse Ember (Max) 进入 Code Arena: WebDev，以 1608 分成为榜上最高分小模型，超过 Claude Haiku 5.5 (High) 的 1595 分和 GPT-6 Luna (Max) 的 1578 分。三者 API 定价同为 $0.10/$0.50 per million tokens，但 Ember 中位成本 $0.03/task，低于 Luna 的 $0.06 和 Haiku 的 $0.11，处于 Pareto 前沿；作者实测其平均约 2 分钟、约 $0.04 完成一个任务。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T18:22:41.000Z","url":"https://x.com/arena/status/2119858226867122459"},{"id":"w675gk2unlouuq5kal57gzs2n","title":"Arena 评测显示 Meta Muse Ember (Max) 以 1608 分登顶 Code Arena WebDev 小模型","summary":"Arena 宣布 Meta 的 Muse Ember (Max) 以 1608 分成为 Code Arena WebDev 中表现最好的小模型，超过 Claude Haiku 5.5 (High) 的 1595 分和 GPT-6 Luna (Max) 的 1578 分。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T18:20:53.000Z","url":"https://x.com/arena/status/2119857775446757697"},{"id":"o37qj3pv5zttwe62nw98299ix","title":"Meta Muse Ember 得分 36 追平 Claude Haiku 5.5，成本仅三分之一","summary":"Artificial Analysis 评测 Meta 最新高效档模型 Muse Ember，Intelligence Index 得分 36，与 Claude Haiku 5.5 (max) 持平，Cost per Task 仅 $0.14 约为后者三分之一。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-09T18:07:16.000Z","url":"https://x.com/ArtificialAnlys/status/2119854348587123007"},{"id":"kcbsqg154krfx1i9rdsyc8qh9","title":"Meta Muse Ember 上线 Meta Model API，定价 $0.10/$0.50 每百万 token","summary":"Meta 宣布 Muse Ember 即日起在 Meta Model API 上提供，定价为每百万输入 token $0.10、每百万输出 token $0.50。详情见其研究博客 https://go.meta.me/muse-ember。","sourceName":"X：AI at Meta (@AIatMeta)","firstParty":false,"publishedAt":"2026-11-09T18:04:17.000Z","url":"https://x.com/AIatMeta/status/2119853597542568405"},{"id":"n82pf82okclz3h0xo2i3y8mfl","title":"Meta 发布 Muse Ember 模型，对标 Claude Haiku 5.5 主打低成本智能体效率","summary":"Meta AI 发布 Muse Ember 模型，面向执行大量小任务的智能体场景，主打更低成本下的智能表现。据 Artificial Analysis Intelligence Index，其性能与 Claude Haiku 5.5 相当，但每任务成本约为其三分之一，并在 GPT-6 Luna 所有推理设置下得分均高于 Luna。","sourceName":"X：AI at Meta (@AIatMeta)","firstParty":false,"publishedAt":"2026-11-09T18:04:16.000Z","url":"https://x.com/AIatMeta/status/2119853595453702580"},{"id":"d1k3rit2ib3jcucmnyw938093","title":"Meta 发布最小高效模型 Muse Ember，面向推理执行与日常智能体工作","summary":"Meta 发布其最小、最高效的模型 Muse Ember，面向复杂推理执行和日常智能体工作。它能跨应用执行工作流、按顺序调用工具、运行测试并做针对性代码修复；具备 1M token 上下文窗口，原生理解文本、图像、音频和视频，可处理大型文档集和多样化输入。","sourceName":"X：AI at Meta (@AIatMeta)","firstParty":false,"publishedAt":"2026-11-09T18:04:15.000Z","url":"https://x.com/AIatMeta/status/2119853591703998787"},{"id":"po9ls7sjtuwzp1hoxm8wls4wq","title":"Meta 发布轻量模型 Muse Ember 主打智能体执行与低成本","summary":"Meta Superintelligence Lab 发布轻量模型 Muse Ember，定位于复杂推理执行和智能体高频任务，如工具调用、编码子任务、路由、信息抽取和长文档解析。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T18:00:00.000Z","url":"https://techcrunch.com/2026/11/09/meta-releases-muse-ember-a-new-lightweight-model-for-agent-execution/"},{"id":"wkqvwm7uv4dk2sdr5ewj33vx5","title":"Artificial Analysis 评测 Meta 新模型 Muse Ember，智能指数 36 分以约三分之一成本持平 Claude Haiku 5.5","summary":"Artificial Analysis 评测 Meta 最新高效档模型 Muse Ember，其 Artificial Analysis Intelligence Index 得分 36，以每任务 $0.14 的成本持平 Claude Haiku 5.5 (max)（$0.41）。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-09T17:59:49.000Z","url":"https://x.com/ArtificialAnlys/status/2119852474081402925"},{"id":"enlrn5uefkni3i4z2zwdl0ebx","title":"Meta 发布最小模型 Muse Ember","summary":"今天发布 Muse Ember——我们最小的模型，每美元智能密度高于同类其他模型。专为智能体全天重复的 token 密集型工作打造：工具调用、编码子任务、路由、信息抽取和长文档解析。即日起可在 Meta Model API 和 Muse Code 中使用。","sourceName":"X：Mark Zuckerberg (@finkd)","firstParty":false,"publishedAt":"2026-11-09T17:54:41.000Z","url":"https://x.com/finkd/status/2119851180948152590"},{"id":"cox936nwax49rkiimi1oicgzu","title":"Meta 发布最小最高效模型 Muse Ember，主打智能体高频任务","summary":"Meta 发布 Muse Ember（muse-ember-1.0），定位最小最高效的复杂推理执行模型，面向工具调用、编码子任务、路由、抽取和长文档解析等智能体日常重复任务。","sourceName":"Meta AI：Research Blog（网页）","firstParty":true,"publishedAt":"2026-11-09T07:00:00.000Z","url":"https://research.meta.ai/blog/muse-ember"},{"id":"tpb612364hatl1n6jezp3xbut","title":"Artificial Analysis 评测 Meta Muse Ember：得分 36 的最便宜模型","summary":"Artificial Analysis 评测 Meta 最新高效档模型 Muse Ember，其在 Intelligence Index 得 36 分，是达到该分数中最便宜的模型，每任务 $0.14，与 Claude Haiku 5.5 (max) 同分但成本约三分之一。","sourceName":"Artificial Analysis 完整文章（网页）","firstParty":true,"publishedAt":"2026-11-08T16:00:00.000Z","url":"https://artificialanalysis.ai/articles/meta-s-muse-ember-is-the-cheapest-model-scoring-36-on-the-intelligence-index"}]},"4a64f241-8892-4af9-9d8a-d75c99724c71":{"publicId":"4a64f241-8892-4af9-9d8a-d75c99724c71","title":"Google 一年内交付四款第八代 TPU","status":"active","sourceCount":6,"reportCount":7,"firstReportAt":"2026-11-09T12:59:02.000Z","latestAt":"2026-11-09T18:19:08.000Z","latest":"Google 扩充第八代 TPU 阵容，新增 TPU 8i Max 与 TPU 8tx","digest":"Google 扩展第八代 TPU 产品线，新增 TPU 8i Max 和 TPU 8tx 两款系统，使一年内发布的第八代 TPU 系统总数达到四款。Google 称这是首次在一年内推出四款不同的 TPU 系统，并称这四款系统覆盖智能体生命周期的各个阶段。\n\nTPU 8i Max 面向超大上下文窗口和单机架最高算力密度，将两颗 TPU 8i 芯片封装在一起，算力、SRAM 和 HBM 带宽均翻倍；TPU 8tx 面向安全与机密推理，数据与模型权重在使用中保持加密隔离，延迟较 TPU 8t 最多降低 2 倍。AMD CEO 苏姿丰称 AMD EPYC 担任 TPU 8tx 的主机处理器。\n\n配套软件方面，Google 称 TorchTPU 可原生运行 PyTorch 和 Hugging Face 模型且无需改写代码，开源 TPU Sync 将 KV 传输延迟降低 90% 以上，Agent Compute Engine 用于减少闲置算力。两款新系统均未公布绝对规格、基准测试、价格和可用区域。","digestUpdatedAt":"2026-11-10T01:30:14.749Z","reports":[{"id":"hr6hduivt94c58w4cmktotumk","title":"Google 扩充第八代 TPU 阵容，新增 TPU 8i Max 与 TPU 8tx","summary":"Google 宣布扩充第八代 TPU 产品组合，新增 TPU 8i Max（面向大上下文窗口和单机架最高算力密度）与 TPU 8tx（面向安全机密推理），是一代之内一年内推出四套不同 TPU 系统的首次。配套软件栈方面，开发者可通过 TorchTPU 原生运行 PyTorch 和 Hugging Face 模型且无需改写代码，开源 TPU Sync 可将 KV 传输延迟降低 90% 以上，Agent Compute Engine 用于消除闲置算力浪费。Sundar Pichai 转发时强调，与等待传统半导体周期不同，硬件工程师与 Google DeepMind 协同设计使创新速度更快。","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-09T18:19:08.000Z","url":"https://x.com/sundarpichai/status/2119857335871164769"},{"id":"d8resym1271jsyrfilimsv5pg","title":"Google 发布 TPU 8i Max 与 TPU 8tx：双芯片 TPU 与机密推理 TPU","summary":"Google 为第八代 TPU 阵容新增 TPU 8i Max 和 TPU 8tx 两款系统配置。TPU 8i Max 将 2 颗 TPU 8i 芯片封装在一起，算力、SRAM 和 HBM 带宽均翻倍；TPU 8tx 基于 TPU 8t 芯片搭配第五代 AMD EPYC 主机，主打机密推理，延迟较 TPU 8t 最多降低 2 倍。两者均未公布绝对规格、基准测试、价格和可用区域。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-09T17:09:54.000Z","url":"https://www.marktechpost.com/2026/11/09/google-tpu-8i-max-tpu-8tx/"},{"id":"bt947en3secfbqdchizophsor","title":"Google Cloud 扩展第八代 TPU 产品线，Lisa Su 确认 AMD EPYC 为 TPU 8tx 主机处理器","summary":"Lisa Su 转发并祝贺 Google Cloud 发布第八代 TPU 新品，包括面向超大上下文窗口和高机架计算密度的 TPU 8i Max，以及面向安全机密推理的 TPU 8tx。Google 称这是首次在一年内推出四款不同 TPU 系统，并开放 TorchTPU 原生运行 PyTorch 与 Hugging Face 模型、开源 TPU Sync 降低 KV 传输延迟超 90%、Agent Compute Engine 减少闲置算力。Lisa Su 补充 AMD EPYC 担任 TPU 8tx 的主机处理器。","sourceName":"X：Lisa Su（AMD CEO） (@LisaSu)","firstParty":false,"publishedAt":"2026-11-09T14:50:59.000Z","url":"https://x.com/LisaSu/status/2119804950968459344"},{"id":"phwieennfk1nppru29uek1b0y","title":"Google 扩展第八代 TPU 阵容，新增两款智能体专用系统","summary":"Google 宣布扩展第八代 TPU 产品线，新增 TPU 8i Max 和 TPU 8tx 两款系统，使一年内发布的第八代 TPU 系统总数达到四款。TPU 8i Max 面向超大上下文窗口和单机架最高算力密度，TPU 8tx 则针对安全与机密推理优化。Google 称这四款系统覆盖智能体生命周期的各个阶段，为开发者提供专用加速器。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-09T13:43:58.000Z","url":"https://x.com/Google/status/2119788086490001906"},{"id":"vczofob3ym334lrcbvbl7q2da","title":"Google 扩展第八代 TPU 并升级开发者软件栈","summary":"除了扩展我们的第八代 TPU 产品组合外，我们还在升级面向开发者的统一、开放软件栈。\n\n了解更多关于我们最新 TPU 系统及开发者更新的信息。 https://goo.gle/3Uo7oKZ","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-09T13:43:58.000Z","url":"https://x.com/Google/status/2119788089354903646"},{"id":"er3rr5v7sarl8mn5a78m3m1fl","title":"Google 发布 TPU 8tx 与 TPU 8i Max，年内 TPU 系统增至四款","summary":"Google 扩展第八代 TPU 产品组合，新增 TPU 8tx 和 TPU 8i Max 两款系统，年内共推出四款 TPU 系统。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-09T13:00:00.000Z","url":"https://blog.google/innovation-and-ai/infrastructure-and-cloud/global-network/tpu-8i-max-and-8tx/"},{"id":"nbyfpljaqpe6cqswrdk9ysczv","title":"Google 一年内交付四款 TPU 变体，加码与 Nvidia 竞争","summary":"Google 为第八代 AI 加速器新增 TPU 8tx 和 TPU 8i Max 两款系统，首次在一年内交付四款 TPU。TPU 8tx 面向机密计算，数据与模型权重在使用中保持加密隔离；TPU 8i Max 在单封装放两颗 TPU 8i 芯片，同机架算力、内存和内存带宽翻倍。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T12:59:02.000Z","url":"https://the-decoder.com/google-ships-four-tpu-variants-in-one-year-as-it-ramps-up-competition-with-nvidia/"}]},"2b6190d7-3612-47d1-9e63-d75e50b8604d":{"publicId":"2b6190d7-3612-47d1-9e63-d75e50b8604d","title":"字节发布 Seedream 5.5 图像模型，豆包接入","status":"active","sourceCount":5,"reportCount":6,"firstReportAt":"2026-11-08T16:00:00.000Z","latestAt":"2026-11-10T10:12:00.000Z","latest":"Seedream 5.5 与 GPT Image 2.6 三大场景横测，30轮连续修改实测对比","digest":"字节跳动 Seed 团队发布图像创作模型 Seedream 5.5，主打像素级可控编辑。官方称，围绕同一作品最多可连续编辑 100 轮，未改动区域在像素级保持不变、不偏色；模型可原生输出带 Alpha 通道的 RGBA 透明素材，最多 100 层透明分层，并改善光照、材质、皮肤纹理和密集小字渲染。豆包随后宣布图片设计能力升级，正式接入该模型。\n\n定价方面，火山引擎称 2K 方图编辑单张 0.28 元，不到 Seedream 5.0 Pro 的一半，生成速度快近 40%，文本 Token 免费；API 延续“输入图 + 输出图”两段计费，本周上线火山方舟。C 端用户可在即梦、豆包、豆包工作体验，Seedream 5.5 系列后续计划推出 Pro 版本。上述性能与价格均为发布方说法。\n\n另有测评作者称，将 Seedream 5.5 与 GPT Image 2.6 用同一张底图连续修改 30 轮，Seedream 5.5 只改动指定区域且画质稳定，Image 2.6 出现人物形变和画面整体漂移；该结论来自单一作者的实测，并非官方验证。","digestUpdatedAt":"2026-11-10T10:24:02.928Z","reports":[{"id":"t5w4qldtkp3k75kw3wukee6ni","title":"Seedream 5.5 与 GPT Image 2.6 三大场景横测，30轮连续修改实测对比","summary":"作者对火山引擎发布的 Seedream 5.5 和 GPT Image 2.6 做横评，用细节密集的底图连续修改30轮，Seedream 5.5 只改动指定区域且画质稳定，Image 2.6 出现人物形变、画面整体漂移和画质变油。Seedream 5.5 还支持最多分离100个图层、输出 RGBA 透明通道，2K 方图改图约两毛八，C 端已接入即梦和豆包，API 本周上线。","sourceName":"公众号：卡尔的AI沃茨","firstParty":false,"publishedAt":"2026-11-10T10:12:00.000Z","url":"https://mp.weixin.qq.com/s/XBIkbitBBnapXzcXfRbuvw"},{"id":"se5kbvyhxw3hmknbcayfnqlnx","title":"豆包接入字节跳动新一代图像创作模型 Seedream 5.5","summary":"豆包官方宣布图片设计能力升级，正式接入字节跳动 Seed 团队此前发布的新一代图像创作模型 Seedream 5.5。该模型支持非编辑区域像素级保持的多轮编辑，可围绕同一作品持续创作多达 100 轮；可原生输出带 Alpha 通道的 RGBA 透明素材；同时改善光照、材质与皮肤纹理质感，并提升复杂字形与密集小字的文字渲染准确性。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T09:02:52.550Z","url":"https://www.ithome.com/1/024/896.htm"},{"id":"wmrqk1kzdl88n952b5ye21at4","title":"字节跳动 Seedream 5.5 发布，支持最多 100 轮像素级稳定图像编辑","summary":"字节跳动 Seed 团队发布图像生成模型 Seedream 5.5，面向专业生产流程。官方称其支持最多 100 轮多轮编辑，未改动区域在像素级保持不变且不偏色，并可生成带透明背景的原生 RGBA 图像，同时更真实地渲染光线、材质与皮肤纹理，更准确呈现密集小字。该模型正通过即梦、豆包、Doubao Work 和 Volcengine Ark 逐步推出，还计划推出 Pro 版本。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T18:50:01.000Z","url":"https://the-decoder.com/bytedances-seedream-5-5-promises-pixel-stable-image-editing-across-100-rounds-without-color-drift/"},{"id":"av7mfri1vioavxjhcvhkxitn1","title":"字节跳动 Seed 团队发布新一代图像创作模型 Seedream 5.5","summary":"字节跳动 Seed 团队发布新一代图像创作模型 Seedream 5.5，重点升级多轮编辑、原生 RGBA 透明素材生成与真实感、文字渲染三项能力，支持围绕同一作品多达 100 轮的持续创作。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-09T09:35:33.007Z","url":"https://www.ithome.com/1/024/379.htm"},{"id":"r7pauzaqgl1gp48pvh4q64x5k","title":"豆包图像创作模型 Seedream 5.5 发布，支持像素级多轮编辑与 RGBA 透明素材","summary":"火山引擎发布豆包图像创作模型 Seedream 5.5，支持像素级可控编辑，实测上百轮连续修改后指定区域外的主体特征、构图比例和光影风格保持一致，并支持原生 RGBA 透明素材生成，最多可输出100层透明分层。相比 Seedream 5.0 Pro，2K 方图编辑单张 0.28 元、便宜60%、生成速度快近40%；API 将于本周上线火山方舟，C 端用户可在即梦、豆包体验。","sourceName":"公众号：火山引擎","firstParty":false,"publishedAt":"2026-11-09T09:07:44.000Z","url":"https://mp.weixin.qq.com/s/35BineRdaBEsMi2Wvefr6Q"},{"id":"xsvt2hlwuovul9sdvazcw7cxk","title":"字节发布 Seedream 5.5 图像创作模型：支持 100 轮编辑与原生 RGBA 透明输出","summary":"字节 Seed 发布新一代图像创作模型 Seedream 5.5，带来三项升级：非编辑区域像素级保持、支持围绕同一作品多达 100 轮连续编辑；新增原生 RGBA 透明素材生成，直接输出带 Alpha 通道的图像，省去抠图；改善光照材质与皮肤纹理表现，并显著提升文字渲染能力。","sourceName":"字节 Seed：Research Feed（网页内嵌数据）","firstParty":true,"publishedAt":"2026-11-08T16:00:00.000Z","url":"https://seed.bytedance.com/zh/blog/%E7%94%9F%E6%88%90%E6%9B%B4%E7%9C%9F%E5%AE%9E-%E7%99%BE%E8%BD%AE%E7%BC%96%E8%BE%91%E6%9B%B4%E7%A8%B3%E5%AE%9A-seedream-5-5-%E5%8F%91%E5%B8%83"}]},"2a8ab25e-4eff-4873-8b94-a826310b395b":{"publicId":"2a8ab25e-4eff-4873-8b94-a826310b395b","title":"虚实传媒首次在X发布北京六岗招聘","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-11-10T11:24:00.000Z","latestAt":"2026-11-10T11:24:00.000Z","latest":"虚实传媒AI Native团队北京招聘六大岗位","digest":"虚实传媒创始人卡兹克首次在X上为公司发布招聘，开放技术/艺术内容主笔、深度报道作者、视频编导、广告客户执行、品牌项目经理、达人运营6个岗位，工作地在北京，提供16薪、五险一金、不打卡考勤和弹性工作，简历投至HR@virxact.com。\n\n卡兹克称，公司现有30多人，签约独家AI博主300+，客户覆盖国内几乎所有AI相关公司；团队全员使用Claude或Codex Coding优化岗位流程，AI会员订阅费由公司报销。","digestUpdatedAt":"2026-11-10T11:44:34.147Z","reports":[{"id":"npikdvxucg2gol9mnq76ev4tf","title":"虚实传媒AI Native团队北京招聘六大岗位","summary":"虚实传媒创始人卡兹克首次在X上为公司招聘，公司现有30多人，签约独家AI博主300+，客户覆盖国内几乎所有AI相关公司。团队全员使用Claude或Codex Coding优化岗位流程，AI会员订阅费由公司报销。此次招聘技术/艺术内容主笔、深度报道作者、视频编导、广告客户执行、品牌项目经理、达人运营6个岗位，base北京，16薪、不打卡、弹性工作，简历投至HR@virxact.com。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-10T11:24:00.000Z","url":"https://x.com/Khazix0918/status/2120115253304586652"}]},"3ef2e80e-4464-431f-bc60-e1c5e7d77933":{"publicId":"3ef2e80e-4464-431f-bc60-e1c5e7d77933","title":"蚂蚁灵波开源触觉基础模型 LingBot-Touch","status":"active","sourceCount":2,"reportCount":2,"firstReportAt":"2026-11-09T19:11:40.000Z","latestAt":"2026-11-10T02:46:47.257Z","latest":"蚂蚁灵波开源触觉基础模型 LingBot-Touch","digest":"蚂蚁灵波科技开源触觉基础模型 LingBot-Touch，用于灵巧操作，基于近 5,000 小时真实触觉数据预训练。\n\n据 IT之家报道，该模型覆盖磁触觉、视触觉和压阻式三类传感原理，输出统一触觉表征，可跨传感器、跨灵巧手、跨模型和跨任务复用。蚂蚁灵波在官方 X 称，其通过统一的异构触觉建模实现上述迁移能力；实际表现尚未由第三方验证。","digestUpdatedAt":"2026-11-10T03:27:05.675Z","reports":[{"id":"v2kttogijk2w2kuk3ip43brpo","title":"蚂蚁灵波开源触觉基础模型 LingBot-Touch","summary":"蚂蚁灵波科技开源触觉基础模型 LingBot-Touch，基于近 5000 小时真实触觉数据预训练，覆盖磁触觉、视触觉和压阻式三类传感原理，输出统一触觉表征，可跨传感器、跨灵巧手、跨模型和跨任务复用。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T02:46:47.257Z","url":"https://www.ithome.com/1/024/701.htm"},{"id":"plmfu1icbz2wx01kigtkwnguk","title":"蚂蚁灵波开源触觉基础模型LingBot-Touch","summary":"当机器人能\"感受\"而不只是\"看见\"，会发生什么变化？🤖✋\n认识 LingBot-Touch，这是我们面向灵巧操作的开源触觉基础模型，基于近 5,000 小时真实触觉数据预训练。\n通过统一的异构触觉建模，LingBot-Touch 支持跨传感器、灵巧手、任务和动作模型的迁移。\n看看它的实际表现。👇 #LingBot #EmbodiedAI #Robotics","sourceName":"Robbyant 蚂蚁灵波（官方 X）","firstParty":false,"publishedAt":"2026-11-09T19:11:40.000Z","url":"https://x.com/robbyant_brain/status/2119870554056651004"}]},"0d0f5f1f-b3ea-4b0f-bd3c-f6735cd0b4dc":{"publicId":"0d0f5f1f-b3ea-4b0f-bd3c-f6735cd0b4dc","title":"xAI 连夜修复 Grok Bot 并重置周限额","status":"active","sourceCount":7,"reportCount":9,"firstReportAt":"2026-11-08T13:17:51.000Z","latestAt":"2026-11-09T22:22:30.000Z","latest":"Grok Bot 每周限额已重置","digest":"xAI 正在连夜修复 Grok Bot 的 token 效率与行为问题，并已为所有用户重置每周使用限额。Elon Musk 称，他刚与 Grok @Bot 工程团队复盘，修复正在连夜实施，用户“明天应该会看到显著改善”；若未见改善，可回复其帖子，团队会立即处理剩余问题。Grok Bot 相关账号 @mattyp 此前也称改进正在进行，并请用户在该帖下回复反馈。\n\n11 月 10 日，Grok Bot 官方账号 @bot 称已为所有 Grok Bot 用户重置每周使用限额，@mattyp、xAI 的 Eric Zakariasson 及 Grok Bot 工程负责人 Lauren Tan 也确认了重置。\n\n修复的具体内容、适用范围和完成时间尚未披露，也没有效率提升幅度的数据；“显著改善”是 Musk 的预期，尚未得到验证。","digestUpdatedAt":"2026-11-09T22:51:57.533Z","reports":[{"id":"sc7m6l0mwvkwsd28wcyh1azu9","title":"Grok Bot 每周限额已重置","summary":"是时候动手做点东西了！！\n\n（引用推文：我们已为所有 Grok Bot 用户重置每周限额。尽情使用吧！）","sourceName":"X：Lingxi Li（SpaceXSI，Grok Bot 工程） (@lingxi)","firstParty":false,"publishedAt":"2026-11-09T22:22:30.000Z","url":"https://x.com/lingxi/status/2119918581530194172"},{"id":"ic8v7uh3japwjya5y2wkh0jiv","title":"Grok Bot 每周限额已重置","summary":"重置正在推送！","sourceName":"X：Lauren Tan（SpaceXSI，Grok Bot 工程负责人） (@poteto)","firstParty":false,"publishedAt":"2026-11-09T19:32:28.000Z","url":"https://x.com/poteto/status/2119875790485741964"},{"id":"xn46b50fezcexcfjrbsndv8t7","title":"Grok Bot 每周限额已重置","summary":"重置 @bot 的每周限额","sourceName":"X：Eric Zakariasson (@ericzakariasson)","firstParty":false,"publishedAt":"2026-11-09T19:30:03.000Z","url":"https://x.com/ericzakariasson/status/2119875182940799080"},{"id":"wz7uqw2s9qlm4a6cq0d8h9n7j","title":"Grok Bot 周限额已重置","summary":"Grok Bot 的每周限额已重置\n\n感谢大家的支持——团队正在昼夜不停地工作","sourceName":"X：Matt Palmer（SpaceXSI，Grok Bot） (@mattyp)","firstParty":false,"publishedAt":"2026-11-09T19:27:38.000Z","url":"https://x.com/mattyp/status/2119874575580492207"},{"id":"d56toetc3hcdjd4hwas283saz","title":"Grok Bot 重置所有用户周限额","summary":"我们已为所有 Grok Bot 用户重置每周限额。\n\n尽情享用！","sourceName":"X：Grok Bot (@bot)","firstParty":false,"publishedAt":"2026-11-09T19:17:20.000Z","url":"https://x.com/bot/status/2119871982946971659"},{"id":"on03qbwvmdyls4kpua3dnftte","title":"马斯克称Grok Bot明日将大幅改进","summary":"Grok @Bot 明天将迎来“大幅改进”","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T02:33:58.000Z","url":"https://x.com/rohanpaul_ai/status/2119619475725287899"},{"id":"q9k7bderhyy5bj6s2x5tsint3","title":"Grok Bot 工程团队连夜修复问题","summary":"刚和 Grok @Bot 工程团队做了一轮圆桌复盘。\n\n修复正在连夜实施，明天你应该会看到显著改善。如果没有，请回复这条帖子，我们会立即处理剩余问题。","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-09T02:25:56.000Z","url":"https://x.com/elonmusk/status/2119617455102333206"},{"id":"bw4baps8s31nkvszvq8qmltzb","title":"Grok Bot 改进 token 效率与行为","summary":"Grok Bot 在 token 效率与行为方面的改进正在进行中\n\n你们许多人在 @bot 上构建了重要的工作流——我们希望继续支持你们\n\n请在这条帖子下回复反馈。我会全部阅读\n\n衷心感谢你们的支持","sourceName":"X：Matt Palmer（SpaceXSI，Grok Bot） (@mattyp)","firstParty":false,"publishedAt":"2026-11-08T16:58:17.000Z","url":"https://x.com/mattyp/status/2119474599708827957"},{"id":"svii78aucgrcj4ccd1gzmtsq0","title":"xAI 正在改进 Grok Bot 的 token 效率","summary":"旨在提升 token 效率和更智能行为的 Grok Bot 修复正在进行中","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-08T13:17:51.000Z","url":"https://x.com/elonmusk/status/2119419126045454531"}]},"1f7bc83b-0722-496f-bb5c-73f3f496580a":{"publicId":"1f7bc83b-0722-496f-bb5c-73f3f496580a","title":"迪士尼与Adobe合作开发定制生成式AI模型","status":"active","sourceCount":3,"reportCount":3,"firstReportAt":"2026-11-09T15:38:56.000Z","latestAt":"2026-11-10T03:26:36.530Z","latest":"Adobe 与迪士尼达成多年战略合作，将 Firefly 等 AI 工具推广至乐园和内容制作","digest":"迪士尼与Adobe在Adobe MAX大会上宣布多年期合作，Adobe将基于Firefly Foundry为迪士尼开发专有的“艺术家主导”生成式AI模型，用于迪士尼的制作流程。Adobe称，该模型将基于迪士尼的角色、场景和视觉风格训练，产出可商用、可用于制作的内容。\n\n根据合作，迪士尼将获得Adobe最新技术的早期访问权限，覆盖迪士尼主题公园、邮轮业务和ESPN内容。Adobe同时成为迪士尼的官方AI创新合作伙伴，计划将AI工具推广至主题乐园、内容制作和体育内容传播等领域。","digestUpdatedAt":"2026-11-10T03:48:00.748Z","reports":[{"id":"mna5obim9zs439keyauqnh8nb","title":"Adobe 与迪士尼达成多年战略合作，将 Firefly 等 AI 工具推广至乐园和内容制作","summary":"Adobe 宣布与华特迪士尼达成多年战略合作，Adobe 成为迪士尼官方 AI 创新合作伙伴，计划将 AI 工具推广至主题乐园、内容制作和体育内容传播等领域。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T03:26:36.530Z","url":"https://www.ithome.com/1/024/731.htm"},{"id":"u8i2b4a6bv581c04ifdfofr56","title":"Disney 与 Adobe 达成多年合作，用 Firefly Foundry 打造品牌安全的定制 AI 模型","summary":"Disney 与 Adobe 在 Adobe MAX 大会宣布多年合作，Adobe 将用 Firefly Foundry 训练基于 Disney 角色、场景和视觉风格的定制模型，产出商用安全、可用于制作的内容。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T16:54:16.000Z","url":"https://the-decoder.com/disney-bets-on-adobes-firefly-to-create-brand-safe-ai-models-for-its-entertainment-empire/"},{"id":"kslgb3sdcqts1m78amfesmx7u","title":"迪士尼与 Adobe 合作开发艺术家主导的专有生成式 AI 模型","summary":"迪士尼与迪士尼？不，The Walt Disney Company 与 Adobe 在 Adobe MAX 大会宣布多年期合作，基于 Firefly Foundry 开发面向迪士尼资产的专有“艺术家主导”生成式 AI 模型。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T15:38:56.000Z","url":"https://www.theverge.com/tech/1029773/disney-adobe-generative-ai-partnership"}]}}};
